function FinanceCarryForwardPanel({
  title,
  basis,
  total,
  rows,
  emptyText,
  help,
  examples,
  details,
  hideRowYear = false,
  onOpenFilter,
}: {
  title: string;
  basis?: string;
  total?: FinanceCarryForwardTotal;
  rows?: FinanceCarryForwardRow[];
  hideRowYear?: boolean;
  emptyText: string;
  help: string | string[];
  examples?: HelperExamples;
  details?: HelperDetails;
  onOpenFilter: (filter: string) => void;
}) {
  const safeTotal = total ?? { count: 0, capital: 0, revenue: 0, total: 0 };
  const getRowLabel = (row: FinanceCarryForwardRow) => {
    const [, mode = ""] = row.filter.split(":");
    if (mode === "previousCarryForward" || mode === "clearedCarryForward") {
      return hideRowYear ? "Previous year liability" : `FY ${row.year} liability`;
    }
    if (mode === "futureClearedCarryForward") return `Cleared in FY ${row.year}`;
    return `FY ${row.year} liability`;
  };
  return (
    <div className="rounded-md border border-border bg-card px-3 py-2.5">
      <div className="flex items-start justify-between gap-2">
        <div>
          <div className="flex items-center gap-1.5">
            <div className="text-[11px] font-semibold text-foreground">{title}</div>
            <FinanceInteractiveHelp label={`${title} help`}>
              <HelperWithExamples items={help} examples={examples} details={details} />
            </FinanceInteractiveHelp>
          </div>
          {basis ? (
            <div className="mt-0.5 text-[10px] font-medium text-muted-foreground">{basis}</div>
          ) : null}
          <div className="mt-1 text-xs text-muted-foreground">{safeTotal.count} liability cases</div>
        </div>
        <div className="text-right text-sm font-semibold">{formatCurrency(safeTotal.total)}</div>
      </div>
      <div className="mt-2 grid grid-cols-2 gap-2 text-[11px] text-muted-foreground">
        <div>Capital {formatCurrency(safeTotal.capital)}</div>
        <div>Revenue {formatCurrency(safeTotal.revenue)}</div>
      </div>
      <div className="mt-3 space-y-1">
        {rows?.length ? (
          rows.map((row) => (
            <button
              key={`${title}-${row.year}`}
              type="button"
              onClick={() => onOpenFilter(row.filter)}
              className="flex w-full items-center rounded border border-border bg-background px-2 py-1.5 text-left text-xs hover:bg-accent"
            >
              <span className="font-medium">{getRowLabel(row)}</span>
            </button>
          ))
        ) : (
          <div className="rounded border border-dashed border-border px-2 py-1.5 text-xs text-muted-foreground">
            {emptyText}
          </div>
        )}
      </div>
    </div>
  );
}

function isFinanceSplitValue(value: SummaryMetricValue): value is FinanceSplitValue {
  return !Array.isArray(value) && typeof value === "object" && value !== null;
}

function LiveStatusSection({
  milestones,
  visibleMilestoneNames,
  rows,
  totalFiles,
  pendingPaymentBreakdown,
  onSupplementaryPendingClick,
  exportDescription,
  onMilestoneToggle,
  onSelectAllMilestones,
  onClearMilestones,
  onLockMilestones,
  lockedMilestoneNames,
  onCountClick,
}: {
  milestones: LiveStatusMilestone[];
  visibleMilestoneNames: string[];
  rows: LiveStatusDivisionRow[];
  totalFiles: number;
  pendingPaymentBreakdown: {
    payment: number;
    advance: number;
    supplementary: number;
    total: number;
  };
  onSupplementaryPendingClick: () => void;
  exportDescription?: string;
  onMilestoneToggle: (milestoneName: string) => void;
  onSelectAllMilestones: () => void;
  onClearMilestones: () => void;
  onLockMilestones: () => void;
  lockedMilestoneNames?: string[];
  onCountClick: (division: string, milestoneName: string) => void;
}) {
  const selectedMilestoneSet = new Set(visibleMilestoneNames);
  const displayedMilestones = milestones.filter((milestone) =>
    selectedMilestoneSet.has(milestone.name),
  );
  const liveTotal = rows.length
    ? rows.reduce((sum, row) => sum + row.total, 0)
    : displayedMilestones.reduce((sum, milestone) => sum + milestone.current, 0);
  const lockMatchesCurrentSelection =
    lockedMilestoneNames !== undefined &&
    lockedMilestoneNames.length === visibleMilestoneNames.length &&
    lockedMilestoneNames.every((name) => selectedMilestoneSet.has(name));

  return (
    <section className="space-y-4">
      <div className="rounded-xl border border-border bg-secondary/35 p-5 shadow-[var(--shadow-card)]">
        <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
          <div className="flex min-w-0 flex-wrap items-baseline gap-x-2">
            <h3 className="text-base font-bold">Division-wise current milestones</h3>
            <p className="text-sm text-muted-foreground">
              Counts are workflow cases, not unique files. One file can contribute several cases; Search lists each matching file once.
            </p>
          </div>
          <div className="flex w-full flex-wrap items-center justify-between gap-2">
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <div className="flex h-8 items-center gap-2 rounded-md border border-border bg-secondary/40 px-2">
                <div className="text-xs font-medium text-muted-foreground">Total Files</div>
                <div className="text-base font-semibold leading-5 tabular-nums">{totalFiles}</div>
              </div>
              <div className="flex h-8 items-center gap-2 rounded-md border border-border bg-secondary/40 px-2">
                <div className="text-xs font-medium text-muted-foreground">Live Cases</div>
                <div className="text-base font-semibold leading-5 tabular-nums">{liveTotal}</div>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-1">
              <button
                type="button"
                onClick={() =>
                  printLiveStatusRowsToPdf(
                    rows,
                    displayedMilestones,
                    "Live status dashboard",
                    exportDescription,
                  )
                }
                disabled={!displayedMilestones.length}
                className="inline-flex h-8 items-center gap-1 rounded-md border border-border bg-secondary/25 px-2 text-xs font-medium hover:bg-accent disabled:pointer-events-none disabled:opacity-50"
              >
                <FileText className="size-3.5" />
                PDF
              </button>
              <button
                type="button"
                onClick={() =>
                  exportLiveStatusRowsToExcel(
                    rows,
                    displayedMilestones,
                    "Live status dashboard",
                    exportDescription,
                  )
                }
                disabled={!displayedMilestones.length}
                className="inline-flex h-8 items-center gap-1 rounded-md border border-border bg-secondary/25 px-2 text-xs font-medium hover:bg-accent disabled:pointer-events-none disabled:opacity-50"
              >
                <FileSpreadsheet className="size-3.5" />
                Excel
              </button>
              <button
                type="button"
                onClick={onSelectAllMilestones}
                className="h-8 rounded-md border border-border bg-secondary/25 px-2 text-xs font-medium hover:bg-accent"
              >
                Select all
              </button>
              <button
                type="button"
                onClick={onClearMilestones}
                className="h-8 rounded-md border border-border bg-secondary/25 px-2 text-xs font-medium hover:bg-accent"
              >
                Clear
              </button>
              <button
                type="button"
                onClick={onLockMilestones}
                className="h-8 rounded-md border border-border bg-secondary/25 px-2 text-xs font-medium hover:bg-accent"
              >
                {lockMatchesCurrentSelection ? "Locked" : "Lock selection"}
              </button>
            </div>
          </div>
        </div>
        <div className="mb-4 rounded-md border border-border bg-secondary/25 p-3">
          <div className="mb-2 text-xs font-semibold uppercase text-muted-foreground">Milestones</div>
          {lockedMilestoneNames !== undefined ? (
            <div className="mb-2 text-xs text-muted-foreground">
              Locked for this login. Change the selection and lock again to update it.
            </div>
          ) : null}
          <div className="flex flex-wrap gap-1.5">
            {milestones.map((milestone) => {
              const checked = selectedMilestoneSet.has(milestone.name);
              const currentCount = getLiveStatusMilestoneDisplayCount(rows, milestone);
              const helperKey = normalizeMilestoneName(milestone.label);
              const helper =
                status2MilestoneHelpers[
                  helperKey === "dp" || helperKey === "deliveryperiodmilestone"
                    ? "deliveryperiod"
                    : helperKey
                ];
              return (
                <div key={milestone.name} className="flex items-center gap-0.5">
                  <label
                    className={
                      "flex h-8 cursor-pointer items-center gap-1.5 rounded-md border px-2 text-xs font-medium transition " +
                      (checked
                        ? "border-primary bg-primary/10 text-foreground"
                        : "border-border bg-card text-muted-foreground hover:bg-accent hover:text-foreground")
                    }
                  >
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={() => onMilestoneToggle(milestone.name)}
                      className="size-3 accent-primary"
                    />
                    <span className="max-w-[150px] truncate">
                      {getWorkflowDisplayLabel(milestone.label)}
                    </span>
                    <span className="rounded bg-secondary px-1.5 py-0.5 tabular-nums">
                      {currentCount}
                    </span>
                  </label>
                  {helper ? (
                    <FloatingHelp label={`${getWorkflowDisplayLabel(milestone.label)} Status-2 help`}>
                      {helper}
                    </FloatingHelp>
                  ) : null}
                </div>
              );
            })}
          </div>
          <div className="mt-3 flex flex-wrap items-center gap-x-2 gap-y-1 border-t border-border/70 pt-2 text-xs text-muted-foreground">
            <span className="font-semibold text-foreground">Total Pending Payments:</span>
            <span>Payment {pendingPaymentBreakdown.payment}</span>
            <span>+</span>
            <span>Advance Payment {pendingPaymentBreakdown.advance}</span>
            <span>+</span>
            <button
              type="button"
              onClick={onSupplementaryPendingClick}
              className="font-medium text-primary underline-offset-2 hover:underline"
            >
              Supplementary Pending {pendingPaymentBreakdown.supplementary}
            </button>
            <span>=</span>
            <span className="font-semibold tabular-nums text-foreground">
              {pendingPaymentBreakdown.total}
            </span>
          </div>
          <div className="mt-1 text-[11px] text-muted-foreground">
            Returned-bill status counts are not added separately.
          </div>
        </div>
        {displayedMilestones.length ? (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[760px] table-fixed border-collapse text-sm">
              <colgroup>
                <col className="w-48" />
                <col className="w-24" />
                {displayedMilestones.map((milestone) => (
                  <col key={milestone.name} className="w-28" />
                ))}
              </colgroup>
              <thead>
                <tr className="border-b border-border text-xs uppercase text-muted-foreground">
                  <th className="px-3 py-2 text-left font-medium">Division</th>
                  <th className="px-3 py-2 text-center font-medium">Total</th>
                  {displayedMilestones.map((milestone) => {
                    const helperKey = normalizeMilestoneName(milestone.label);
                    const helper =
                      status2MilestoneHelpers[
                        helperKey === "dp" || helperKey === "deliveryperiodmilestone"
                          ? "deliveryperiod"
                          : helperKey
                      ];
                    const label = getWorkflowDisplayLabel(milestone.label);
                    return (
                      <th key={milestone.name} className="px-3 py-2 text-center font-medium">
                        <span className="inline-flex max-w-full items-center justify-center gap-1.5 align-middle">
                          <span className="truncate">{label}</span>
                          {helper ? (
                            <TooltipProvider delayDuration={150}>
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <button
                                    type="button"
                                    className="inline-flex size-5 shrink-0 cursor-help items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground focus:outline-none focus:ring-2 focus:ring-ring/40"
                                    aria-label={`${label} Status-2 help`}
                                  >
                                    <Info className="size-3.5" />
                                  </button>
                                </TooltipTrigger>
                                <TooltipContent
                                  side="top"
                                  align="start"
                                  className="w-fit max-w-[min(48rem,calc(100vw-2rem))] border border-border bg-background p-2 text-foreground shadow-lg text-xs leading-relaxed"
                                >
                                  <HelperBulletList items={helper} />
                                </TooltipContent>
                              </Tooltip>
                            </TooltipProvider>
                          ) : null}
                        </span>
                      </th>
                    );
                  })}
                </tr>
              </thead>
              <tbody>
                {rows.map((row) => (
                  <tr key={row.division} className="border-b border-border/60 last:border-0">
                    <td className="px-3 py-2 font-medium">{row.division}</td>
                    <td className="px-3 py-2 text-center font-semibold tabular-nums">
                      {row.total}
                    </td>
                    {displayedMilestones.map((milestone) => {
                      const count = getLiveStatusRowMilestoneCount(row, milestone);
                      return (
                        <td key={milestone.name} className="px-2 py-2 text-center">
                          {count > 0 ? (
                            <button
                              type="button"
                              onClick={() => onCountClick(row.division, milestone.name)}
                              className="h-8 min-w-12 rounded-md border border-border bg-secondary/35 px-2 font-semibold tabular-nums transition hover:bg-accent hover:ring-2 hover:ring-ring/25"
                              aria-label={`Open ${count} ${row.division} files at ${getWorkflowDisplayLabel(milestone.label)}`}
                            >
                              {count}
                            </button>
                          ) : (
                            <span className="inline-flex h-8 min-w-12 items-center justify-center rounded-md border border-border/60 bg-card px-2 text-muted-foreground tabular-nums">
                              0
                            </span>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="rounded-md border border-dashed border-border p-5 text-sm text-muted-foreground">
            Select at least one milestone to show division-wise counts.
          </div>
        )}
        {!rows.length && displayedMilestones.length ? (
          <div className="mt-3 text-sm text-muted-foreground">No division data available.</div>
        ) : null}
      </div>
    </section>
  );
}

function getLiveStatusRowMilestoneCount(
  row: LiveStatusDivisionRow,
  milestone: LiveStatusMilestone,
) {
  const exactCount = row.counts[milestone.name];
  if (exactCount !== undefined) return exactCount;
  const normalizedMilestone = normalizeMilestoneName(milestone.name);
  const matchingEntry = Object.entries(row.counts).find(
    ([name]) => normalizeMilestoneName(name) === normalizedMilestone,
  );
  return matchingEntry ? matchingEntry[1] : 0;
}

function getLiveStatusMilestoneDisplayCount(
  rows: LiveStatusDivisionRow[],
  milestone: LiveStatusMilestone,
) {
  if (
    !rows.length ||
    !rows.some((row) =>
      Object.keys(row.counts).some(
        (name) => normalizeMilestoneName(name) === normalizeMilestoneName(milestone.name),
      ),
    )
  ) {
    return milestone.current;
  }
  return rows.reduce((sum, row) => sum + getLiveStatusRowMilestoneCount(row, milestone), 0);
}

type Status4TableRow = {
  key: string;
  label: string;
  sortValue: string | number;
  files: FileRecord[];
  total: number;
  metrics: Record<string, Status4MilestoneMetrics>;
  fiscalYear?: string;
  monthKey?: string;
  minValue?: number;
  maxValue?: number;
  onLabelClick?: () => void;
};

function Status4Section({
  files,
  milestones,
  visibleMilestoneNames,
  totalFiles,
  liveCases,
  valueThresholdLevels,
  drill,
  sortKey,
  sortDirection,
  loading,
  error,
  exportDescription,
  onDrillChange,
  onSortChange,
  onCountClick,
}: {
  files: FileRecord[];
  milestones: LiveStatusMilestone[];
  visibleMilestoneNames: string[];
  totalFiles: number;
  liveCases: number;
  valueThresholdLevels: ValueThresholdLevel[];
  drill: Status4DrillState;
  sortKey: Status4SortKey;
  sortDirection: AnalyticsSortDirection;
  loading: boolean;
  error?: string;
  exportDescription?: string;
  onDrillChange: (drill: Status4DrillState) => void;
  onSortChange: (sortKey: Status4SortKey) => void;
  onCountClick: (filter: Status4SearchFilter) => void;
}) {
  const [resultView, setResultView] = useState<ResultView>("table");
  const [status4ChartFiscalYear, setStatus4ChartFiscalYear] = useState("");
  const selectedMilestoneSet = new Set(visibleMilestoneNames);
  const displayedMilestones = getStatus4Milestones(
    milestones.filter((milestone) => selectedMilestoneSet.has(milestone.name)),
  );
  const thresholdRanges = getStatus4ThresholdRanges(valueThresholdLevels);
  const rows = getStatus4DisplayRows({
    files,
    milestones: displayedMilestones,
    drill,
    thresholdRanges,
    sortKey,
    sortDirection,
    onDrillChange,
  });
  const tableLabel = getStatus4TableLabel(drill);
  const breadcrumbItems = getStatus4BreadcrumbItems(drill);
  const canShowTable =
    displayedMilestones.length > 0 && (!drill.fiscalYear || drill.mode !== undefined);
  const chartFiscalYears = Array.from(new Set(rows
    .map((row) => row.fiscalYear)
    .filter((year): year is string => Boolean(year && year !== "undated"))))
    .sort((a, b) => getStatus4FySortValue(b) - getStatus4FySortValue(a));
  const selectedChartFiscalYear = chartFiscalYears.includes(status4ChartFiscalYear)
    ? status4ChartFiscalYear
    : chartFiscalYears[0] ?? "";
  const chartScopeRows = rows.filter((row) => row.fiscalYear === selectedChartFiscalYear);
  const chartRows = displayedMilestones.map((milestone) => {
    const metrics = chartScopeRows.reduce(
      (total, row) => {
        const rowMetrics = row.metrics[milestone.name];
        if (!rowMetrics) return total;
        total.applicable += rowMetrics.applicable;
        total.cleared += rowMetrics.cleared;
        total.current += rowMetrics.current;
        return total;
      },
      { applicable: 0, cleared: 0, current: 0 },
    );
    return {
      label: getWorkflowDisplayLabel(milestone.label),
      milestone: milestone.name,
      metrics,
    };
  });
  const status4ChartPlot: ExportPlot | undefined =
    (resultView === "bar" || resultView === "column") && chartRows.length
      ? {
          kind: "bar",
          title: `${tableLabel} · ${selectedChartFiscalYear} · Milestone comparison`,
          measure: "Cleared, Current, and Balance counts by milestone",
          unit: "Files",
          xAxisTitle: "Milestone",
          yAxisTitle: "Files",
          categories: chartRows.map((row) => row.label),
          series: [
            { name: "Cleared", color: getStatus4MetricColor("cleared"), values: chartRows.map((row) => row.metrics.cleared) },
            { name: "Current", color: getStatus4MetricColor("current"), values: chartRows.map((row) => row.metrics.current) },
            { name: "Balance", color: getChartColorAt(2), values: chartRows.map((row) => Math.max(0, row.metrics.applicable - row.metrics.cleared - row.metrics.current)) },
          ],
        }
      : undefined;

  return (
    <section className="space-y-4">
      <div className="rounded-xl border border-border bg-secondary/35 p-5 shadow-[var(--shadow-card)]">
        <div className="mb-4 space-y-3">
          <div>
            <h3 className="text-base font-bold">{tableLabel}</h3>
            {breadcrumbItems.length ? (
              <div className="mt-1 flex flex-wrap items-center gap-1.5 text-xs text-muted-foreground">
                {breadcrumbItems.map((item, index) => (
                  <Fragment key={`${item.label}-${index}`}>
                    {index > 0 ? <span>/</span> : null}
                    {item.drill ? (
                      <button
                        type="button"
                        onClick={() => onDrillChange(item.drill!)}
                        className="font-medium text-foreground hover:text-primary"
                      >
                        {item.label}
                      </button>
                    ) : (
                      <span>{item.label}</span>
                    )}
                  </Fragment>
                ))}
              </div>
            ) : null}
          </div>
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="flex flex-wrap items-center gap-2">
              <div className="flex h-8 items-center gap-2 rounded-md border border-border bg-secondary/40 px-2">
                <div className="text-xs font-medium text-muted-foreground">Total Files</div>
                <div className="text-base font-semibold leading-5 tabular-nums">{totalFiles}</div>
              </div>
              <div className="flex h-8 items-center gap-2 rounded-md border border-border bg-secondary/40 px-2">
                <div className="text-xs font-medium text-muted-foreground">Live Cases</div>
                <div className="text-base font-semibold leading-5 tabular-nums">{liveCases}</div>
              </div>
            </div>
            <div className="flex flex-wrap items-center justify-end gap-2">
              <TableChartToggle
                value={resultView}
                onChange={setResultView}
                label="Status-4 result view"
                views={["table", "bar", "column"]}
              />
              <div className="flex h-8 items-center rounded-md border border-border bg-secondary/40 p-0.5">
                <button
                  type="button"
                  onClick={() =>
                    printStatus4RowsToPdf(rows, displayedMilestones, tableLabel, exportDescription, status4ChartPlot)
                  }
                  disabled={!canShowTable || !rows.length}
                  className="flex h-full items-center gap-1 rounded px-2 text-xs font-medium text-muted-foreground transition hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-50"
                >
                  <FileText className="size-3.5" />
                  PDF
                </button>
                <button
                  type="button"
                  onClick={() =>
                    exportStatus4RowsToExcel(
                      rows,
                      displayedMilestones,
                      tableLabel,
                      getStatus4RowHeaderLabel(drill),
                      exportDescription,
                      status4ChartPlot,
                    )
                  }
                  disabled={!canShowTable || !rows.length}
                  className="flex h-full items-center gap-1 rounded px-2 text-xs font-medium text-muted-foreground transition hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-50"
                >
                  <FileSpreadsheet className="size-3.5" />
                  Excel
                </button>
              </div>
            </div>
          </div>
        </div>

        {loading ? (
          <div className="mb-3 rounded-md border border-border bg-secondary/25 px-3 py-2 text-sm text-muted-foreground">
            Loading Status-4 data...
          </div>
        ) : null}
        {error ? (
          <div className="mb-3 rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">
            Status-4 data unavailable: {error}
          </div>
        ) : null}

        <Status4HelperToolbar drill={drill} />

        {drill.fiscalYear && !drill.mode ? (
          <div className="grid gap-3 sm:grid-cols-2">
            <button
              type="button"
              onClick={() => onDrillChange({ fiscalYear: drill.fiscalYear, mode: "threshold" })}
              className="rounded-md border border-border bg-secondary/30 p-4 text-left hover:bg-accent"
            >
              <div className="text-sm font-semibold">Value Threshold</div>
              <div className="mt-1 text-xs text-muted-foreground">
                Preset value ranges for the selected Status-4 milestones.
              </div>
            </button>
            <button
              type="button"
              onClick={() => onDrillChange({ fiscalYear: drill.fiscalYear, mode: "monthwise" })}
              className="rounded-md border border-border bg-secondary/30 p-4 text-left hover:bg-accent"
            >
              <div className="text-sm font-semibold">Monthwise</div>
              <div className="mt-1 text-xs text-muted-foreground">
                Month rows first, then value range breakup for a selected month.
              </div>
            </button>
          </div>
        ) : null}

        {!displayedMilestones.length ? (
          <div className="rounded-md border border-dashed border-border p-5 text-sm text-muted-foreground">
            Select at least one Status-2 milestone to show Status-4 counts.
          </div>
        ) : null}

        {canShowTable && (resultView === "bar" || resultView === "column") ? (
          <div className="space-y-3">
            {chartFiscalYears.length ? (
              <div role="tablist" aria-label="Status-4 chart year" className="flex flex-wrap gap-1 border-b border-border">
                {chartFiscalYears.map((year) => (
                  <button key={year} type="button" role="tab" aria-selected={selectedChartFiscalYear === year}
                    onClick={() => setStatus4ChartFiscalYear(year)}
                    className={`border-b-2 px-3 py-2 text-xs font-medium ${selectedChartFiscalYear === year ? "border-primary text-foreground" : "border-transparent text-muted-foreground hover:text-foreground"}`}>
                    {year}
                  </button>
                ))}
              </div>
            ) : null}
            <Status4MilestoneComparisonChart
              rows={chartRows}
              orientation={resultView === "column" ? "vertical" : "horizontal"}
              onCountClick={(milestone, metric) =>
                onCountClick({ milestone, metric, fiscalYear: selectedChartFiscalYear, monthKey: drill.monthKey })
              }
            />
          </div>
        ) : canShowTable ? (
          <Status4Table
            rows={rows}
            milestones={displayedMilestones}
            rowHeaderLabel={getStatus4RowHeaderLabel(drill)}
            sortKey={sortKey}
            sortDirection={sortDirection}
            onSortChange={onSortChange}
            onCountClick={onCountClick}
          />
        ) : null}
      </div>
    </section>
  );
}

function Status4Table({
  rows,
  milestones,
  rowHeaderLabel,
  sortKey,
  sortDirection,
  onSortChange,
  onCountClick,
}: {
  rows: Status4TableRow[];
  milestones: LiveStatusMilestone[];
  rowHeaderLabel: string;
  sortKey: Status4SortKey;
  sortDirection: AnalyticsSortDirection;
  onSortChange: (sortKey: Status4SortKey) => void;
  onCountClick: (filter: Status4SearchFilter) => void;
}) {
  const grandTotal = rows.reduce((sum, row) => sum + row.total, 0);

  return rows.length ? (
    <div className="overflow-x-auto">
      <table className="w-full min-w-[760px] table-fixed border-collapse text-sm">
        <colgroup>
          <col className="w-44" />
          <col className="w-24" />
          {milestones.map((milestone) => (
            <col key={milestone.name} className="w-32" />
          ))}
        </colgroup>
        <thead>
          <tr className="border-b border-border text-xs uppercase text-muted-foreground">
            <Status4SortableHeader
              label={rowHeaderLabel}
              sortKey="label"
              activeSortKey={sortKey}
              sortDirection={sortDirection}
              onSortChange={onSortChange}
              align="left"
            />
            <Status4SortableHeader
              label="Total"
              sortKey="total"
              activeSortKey={sortKey}
              sortDirection={sortDirection}
              onSortChange={onSortChange}
            />
            {milestones.map((milestone) => (
              <Status4SortableHeader
                key={milestone.name}
                label={getWorkflowDisplayLabel(milestone.label)}
                sortKey={`milestone:${milestone.name}`}
                activeSortKey={sortKey}
                sortDirection={sortDirection}
                onSortChange={onSortChange}
              />
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.key} className="border-b border-border/60 last:border-0">
              <td className="px-3 py-2 font-medium">
                {row.onLabelClick ? (
                  <button
                    type="button"
                    onClick={row.onLabelClick}
                    className="text-left text-foreground hover:text-primary hover:underline"
                  >
                    {row.label}
                  </button>
                ) : (
                  row.label
                )}
              </td>
              <td className="px-3 py-2 text-center font-semibold tabular-nums">{row.total}</td>
              {milestones.map((milestone) => {
                const metrics =
                  row.metrics[milestone.name] ??
                  ({ applicable: 0, cleared: 0, current: 0 } satisfies Status4MilestoneMetrics);
                return (
                  <td key={milestone.name} className="px-2 py-2 text-center">
                    <Status4MetricCell
                      metrics={metrics}
                      milestone={milestone.name}
                      fiscalYear={row.fiscalYear}
                      monthKey={row.monthKey}
                      minValue={row.minValue}
                      maxValue={row.maxValue}
                      onCountClick={onCountClick}
                    />
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr className="border-t border-border bg-secondary/25 font-semibold">
            <td className="px-3 py-2">Total</td>
            <td className="px-3 py-2 text-center tabular-nums">{grandTotal}</td>
            {milestones.length ? <td colSpan={milestones.length} className="px-2 py-2" /> : null}
          </tr>
        </tfoot>
      </table>
    </div>
  ) : (
    <div className="rounded-md border border-dashed border-border p-5 text-sm text-muted-foreground">
      No Status-4 data available for the selected scope.
    </div>
  );
}

function Status4MilestoneComparisonChart({
  rows,
  orientation,
  onCountClick,
}: {
  rows: Array<{ label: string; milestone: string; metrics: Status4MilestoneMetrics }>;
  orientation: "horizontal" | "vertical";
  onCountClick: (milestone: string, metric: Status4MetricKey) => void;
}) {
  const maximum = Math.max(1, ...rows.map((row) => Math.max(row.metrics.applicable, row.metrics.cleared + row.metrics.current)));
  const targetStep = maximum / 4;
  const stepMagnitude = 10 ** Math.floor(Math.log10(Math.max(1, targetStep)));
  const normalizedStep = targetStep / stepMagnitude;
  const axisStep = ([1, 2, 2.5, 5, 10].find((candidate) => candidate >= normalizedStep) ?? 10) * stepMagnitude;
  const axisMaximum = Math.ceil(maximum / axisStep) * axisStep;
  const tickValues = Array.from({ length: Math.round(axisMaximum / axisStep) + 1 }, (_, index) => axisMaximum - index * axisStep);
  const milestoneLabelWidth = Math.min(220, Math.max(72, ...rows.map((row) => row.label.length * 7.5 + 8)));
  const horizontalGridColumns = `${milestoneLabelWidth}px minmax(0, 1fr)`;
  const legend = (
    <div className="flex flex-wrap items-center gap-4 text-sm text-muted-foreground">
      <span className="inline-flex items-center gap-1.5">
        <span className="size-2.5 rounded-sm bg-gray-300" />
        Balance
      </span>
      {(["cleared", "current"] as const).map((metric) => (
        <span key={metric} className="inline-flex items-center gap-1.5">
          <span className="size-2.5 rounded-sm" style={{ backgroundColor: getStatus4MetricColor(metric) }} />
          {getStatus4MetricLabel(metric)}
        </span>
      ))}
    </div>
  );

  if (orientation === "vertical") {
    const chartHeight = 320;
    const plotTopPadding = 24;
    const plotHeight = chartHeight + plotTopPadding;
    return (
      <div
        data-chart-copy-area
        className="mx-auto w-full rounded-none border border-border bg-background p-4"
        style={{ maxWidth: `${Math.min(960, Math.max(420, rows.length * 52 + 60))}px` }}
      >
        <h3 className="mb-2 text-center text-xl font-semibold text-foreground">Status-4 milestone comparison</h3>
        <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
          <span className="text-base font-medium text-muted-foreground">File Count</span>
          {legend}
          <ChartCopyButton />
        </div>
        <div role="group" aria-label="Status-4 milestone comparison column chart" className="overflow-hidden">
          <div className="relative w-full">
            <div className="absolute left-8 right-11 top-0" style={{ height: plotHeight }} aria-hidden="true">
              <svg className="absolute inset-0 h-full w-full" viewBox={`0 0 100 ${plotHeight}`} preserveAspectRatio="none">
                {tickValues.map((value, index) => <line key={`h${value}`} x1="0" x2="100" y1={plotTopPadding + index * chartHeight / (tickValues.length - 1)} y2={plotTopPadding + index * chartHeight / (tickValues.length - 1)} stroke="#cbd5e1" strokeWidth="1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />)}
                {Array.from({ length: rows.length + 1 }, (_, index) => <line key={`v${index}`} x1={index * 100 / rows.length} x2={index * 100 / rows.length} y1={plotTopPadding} y2={plotHeight} stroke="#cbd5e1" strokeWidth="1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />)}
              </svg>
              {tickValues.map((value, index) => (
                <div
                  key={`${value}-${index}`}
                  className="absolute inset-x-0"
                  style={{ top: plotTopPadding + (index / (tickValues.length - 1)) * chartHeight }}
                >
                  <span className="absolute -left-11 -top-2 w-9 text-right text-sm tabular-nums text-muted-foreground">
                    {value}
                  </span>
                </div>
              ))}
            </div>
            <div className="relative ml-10 flex items-end gap-0.5 px-1 pr-11" style={{ height: plotHeight }}>
              {rows.map((row) => {
                const balance = Math.max(0, row.metrics.applicable - row.metrics.cleared - row.metrics.current);
                const totalHeight = (row.metrics.applicable / axisMaximum) * chartHeight;
                const barInnerHeight = totalHeight;
                const segmentHeight = (value: number) => row.metrics.applicable > 0
                  ? (value / row.metrics.applicable) * barInnerHeight
                  : 0;
                const segments = [
                  { key: "cleared" as const, label: "Cleared", value: row.metrics.cleared, color: getStatus4MetricColor("cleared") },
                  { key: "current" as const, label: "Current", value: row.metrics.current, color: getStatus4MetricColor("current") },
                  { key: "balance" as const, label: "Balance", value: balance, color: getChartColorAt(2) },
                ];

                return (
                  <div key={row.milestone} className="relative h-full min-w-0 flex-1">
                    <div
                      className="absolute bottom-0 left-1/2 flex -translate-x-1/2 flex-col-reverse overflow-hidden"
                      style={{
                        height: totalHeight,
                        width: "min(24px, 52%)",
                      }}
                    >
                      {segments.map((segment) => {
                        const height = segmentHeight(segment.value);
                        const content = <span className="block h-full w-full" style={{ backgroundColor: segment.color }} />;
                        return (
                          <TooltipProvider key={segment.key} delayDuration={150}>
                            <Tooltip>
                              <TooltipTrigger asChild>
                                {segment.key === "balance" ? (
                                  <span className="block w-full shrink-0" style={{ height }}>{content}</span>
                                ) : (
                                  <button
                                    type="button"
                                    disabled={segment.value === 0}
                                    onClick={() => onCountClick(row.milestone, segment.key)}
                                    aria-label={`${segment.label}: ${segment.value}`}
                                    className="block w-full shrink-0 disabled:cursor-default"
                                    style={{ height }}
                                  >
                                    {content}
                                  </button>
                                )}
                              </TooltipTrigger>
                              <TooltipContent>{segment.label}: {segment.value}</TooltipContent>
                            </Tooltip>
                          </TooltipProvider>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
            <div className="ml-10 flex h-[120px] gap-0.5 px-1 pr-11 pt-3">
              {rows.map((row) => (
                <div key={row.milestone} className="relative min-w-0 flex-1">
                  <span
                    className="absolute left-1/2 top-3 whitespace-nowrap text-sm font-medium leading-tight text-muted-foreground"
                    style={{ transform: "rotate(55deg)", transformOrigin: "top left" }}
                  >
                    {row.label}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
      <div
        data-chart-copy-area
        className="mx-auto w-full rounded-none border border-border bg-background p-4"
        style={{ maxWidth: `${Math.min(960, Math.max(420, rows.length * 52 + 60))}px` }}
      >
      <h3 className="mb-2 text-center text-xl font-semibold text-foreground">Status-4 milestone comparison</h3>
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        {legend}
        <ChartCopyButton />
      </div>
      <div role="group" aria-label="Status-4 milestone comparison chart" className="space-y-0">
        <div className="grid gap-3" style={{ gridTemplateColumns: horizontalGridColumns }}>
          <span className="text-base font-medium text-muted-foreground">Milestone</span>
          <span aria-hidden="true" className="h-7" />
        </div>
        {rows.map((row) => {
          const balance = Math.max(0, row.metrics.applicable - row.metrics.cleared - row.metrics.current);
          const segments = [
            { key: "cleared" as const, label: "Cleared", value: row.metrics.cleared, color: getStatus4MetricColor("cleared") },
            { key: "current" as const, label: "Current", value: row.metrics.current, color: getStatus4MetricColor("current") },
            { key: "balance" as const, label: "Balance", value: balance, color: getChartColorAt(2) },
          ];
          return (
            <div key={row.milestone} className="grid items-center gap-3 py-1" style={{ gridTemplateColumns: horizontalGridColumns }}>
              <span className="text-sm font-medium">{row.label}</span>
              <div className="relative flex h-6 items-center">
                <svg aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" viewBox="0 0 100 24" preserveAspectRatio="none">
                  {tickValues.map((value, index) => <line key={`v${value}`} x1={index / (tickValues.length - 1) * 100} x2={index / (tickValues.length - 1) * 100} y1="0" y2="24" stroke="#cbd5e1" strokeWidth="1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />)}
                  <line x1="0" x2="100" y1="0" y2="0" stroke="#cbd5e1" strokeWidth="1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />
                  <line x1="0" x2="100" y1="24" y2="24" stroke="#cbd5e1" strokeWidth="1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />
                </svg>
                <div className="absolute left-0 top-1/2 z-[1] flex h-2 -translate-y-1/2" style={{ width: `${row.metrics.applicable / axisMaximum * 100}%` }}>
                  {segments.map((segment) => {
                    const width = row.metrics.applicable > 0 ? (segment.value / row.metrics.applicable) * 100 : 0;
                    const content = <span className="block h-full w-full" style={{ backgroundColor: segment.color }} />;
                    const trigger = segment.key === "balance" ? (
                      <span className="block h-full min-w-0 shrink-0" aria-label={`Balance: ${segment.value}`} style={{ width: `${width}%` }}>{content}</span>
                    ) : (
                      <button type="button" disabled={segment.value === 0}
                        onClick={() => onCountClick(row.milestone, segment.key)}
                        aria-label={`${segment.label}: ${segment.value}`}
                        className="block h-full min-w-0 shrink-0 disabled:cursor-default"
                        style={{ width: `${width}%` }}>{content}</button>
                    );
                    return (
                      <TooltipProvider key={segment.key} delayDuration={150}>
                        <Tooltip><TooltipTrigger asChild>{trigger}</TooltipTrigger><TooltipContent>{segment.label}: {segment.value}</TooltipContent></Tooltip>
                      </TooltipProvider>
                    );
                  })}
                </div>
              </div>
            </div>
          );
        })}
        <div className="grid gap-3 pt-1" style={{ gridTemplateColumns: horizontalGridColumns }}>
          <span />
          <div className="flex justify-between text-xs tabular-nums text-muted-foreground">{[...tickValues].reverse().map((value) => <span key={value}>{value.toLocaleString("en-IN")}</span>)}</div>
        </div>
        <div className="grid gap-3 pt-1 text-base font-medium text-muted-foreground" style={{ gridTemplateColumns: horizontalGridColumns }}>
          <span />
          <span className="text-center">File Count</span>
        </div>
      </div>
    </div>
  );
}

function getStatus4MetricColor(metric: Status4MetricKey) {
  return getChartColorAt(metric === "cleared" ? 0 : 1);
}

function getChartColorAt(index: number) {
  return getRankedChartColor(index, store.getSettings().chartColorOrder);
}

function Status4SortableHeader({
  label,
  sortKey,
  activeSortKey,
  sortDirection,
  onSortChange,
  align = "center",
}: {
  label: string;
  sortKey: Status4SortKey;
  activeSortKey: Status4SortKey;
  sortDirection: AnalyticsSortDirection;
  onSortChange: (sortKey: Status4SortKey) => void;
  align?: "left" | "center";
}) {
  const active = sortKey === activeSortKey;
  return (
    <th className={`px-3 py-2 font-medium ${align === "left" ? "text-left" : "text-center"}`}>
      <button
        type="button"
        onClick={() => onSortChange(sortKey)}
        className="inline-flex max-w-full items-center gap-1 hover:text-foreground"
      >
        <span className="truncate">{label}</span>
        {active ? <span>{sortDirection === "asc" ? "A-Z" : "Z-A"}</span> : null}
      </button>
    </th>
  );
}

function Status4MetricCell({
  metrics,
  milestone,
  fiscalYear,
  monthKey,
  minValue,
  maxValue,
  onCountClick,
}: {
  metrics: Status4MilestoneMetrics;
  milestone: string;
  fiscalYear?: string;
  monthKey?: string;
  minValue?: number;
  maxValue?: number;
  onCountClick: (filter: Status4SearchFilter) => void;
}) {
  return (
    <div className="overflow-hidden rounded-md border border-border bg-card text-xs font-semibold tabular-nums">
      {getStatus4MetricKeys().map((metric) => {
        const value = metrics[metric] ?? 0;
        const label = getStatus4MetricLabel(metric);
        return value > 0 && fiscalYear ? (
          <button
            key={metric}
            type="button"
            aria-label={`${label}: ${value}`}
            onClick={() =>
              onCountClick({ milestone, metric, fiscalYear, monthKey, minValue, maxValue })
            }
            className="flex h-7 w-full items-center justify-center border-b border-border px-2 text-center text-foreground last:border-b-0 hover:bg-accent"
            title={label}
          >
            {value}
          </button>
        ) : (
          <span
            key={metric}
            className="flex h-7 items-center justify-center border-b border-border px-2 text-center text-muted-foreground last:border-b-0"
            title={label}
          >
            {value}
          </span>
        );
      })}
    </div>
  );
}

function getStatus4MetricKeys(): Status4MetricKey[] {
  return ["applicable", "cleared", "current"];
}

function getStatus4MetricLabel(metric: Status4MetricKey) {
  if (metric === "applicable") return "Applicable";
  if (metric === "cleared") return "Cleared";
  return "Current";
}

function getStatus4BreadcrumbItems(drill: Status4DrillState) {
  const items: Array<{ label: string; drill?: Status4DrillState }> = drill.fiscalYear
    ? [{ label: "FY", drill: {} }]
    : [];
  if (drill.fiscalYear) {
    items.push({
      label: drill.fiscalYear,
      drill: drill.mode ? { fiscalYear: drill.fiscalYear } : undefined,
    });
  }
  if (drill.mode === "threshold") items.push({ label: "Value Threshold" });
  if (drill.mode === "monthwise") {
    items.push({
      label: "Monthwise",
      drill: drill.monthKey ? { fiscalYear: drill.fiscalYear, mode: "monthwise" } : undefined,
    });
  }
  if (drill.monthKey) items.push({ label: formatMonthKeyLabel(drill.monthKey) });
  return items;
}

function getStatus4TableLabel(drill: Status4DrillState) {
  if (!drill.fiscalYear) return "FY wise current status";
  if (!drill.mode) return `${drill.fiscalYear} drill-down`;
  if (drill.mode === "threshold") return `${drill.fiscalYear} value threshold status`;
  if (drill.monthKey) return `${formatMonthKeyLabel(drill.monthKey)} value threshold status`;
  return `${drill.fiscalYear} monthwise status`;
}

function getStatus4RowHeaderLabel(drill: Status4DrillState) {
  if (!drill.fiscalYear) return "FY";
  if (drill.mode === "monthwise" && !drill.monthKey) return "Month";
  return "Value Range";
}

function Status4HelperToolbar({ drill }: { drill: Status4DrillState }) {
  const helpers = getStatus4HelperItems(drill);
  return (
    <div className="mb-4 rounded-lg border border-border bg-secondary/20 px-3 py-2">
      <div className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        Status-4 helper
      </div>
      <div className="flex flex-wrap gap-2">
        {helpers.map((helper) => (
          <div
            key={helper.label}
            className="inline-flex items-center gap-1.5 rounded-full border border-border bg-card px-2 py-1 text-xs"
          >
            <span className="font-medium text-foreground">{helper.label}</span>
            <FloatingHelp label={`${helper.label} help`}>{helper.items}</FloatingHelp>
          </div>
        ))}
      </div>
    </div>
  );
}

function getStatus4HelperItems(drill: Status4DrillState): Array<{
  label: string;
  items: string[];
}> {
  const common = [
    {
      label: "Total",
      items: [
        "The count is files, not stages or S.O.s.",
        "Cancelled demands are left out. Cancelling an S.O. does not remove the file from this total.",
      ],
    },
    {
      label: "Applicable",
      items: [
        "Files counted as applicable must pass through this stage.",
        "Example: IFA applies when IFA is marked Yes; TCEC stages apply to TCEC files.",
      ],
    },
    {
      label: "Cleared",
      items: [
        "Cleared files are applicable files with this stage completed.",
        "A cancelled S.O. still counts as placed because it was placed before it was cancelled.",
        "Click a non-zero count to open matching files.",
      ],
    },
    {
      label: "Current",
      items: [
        "Files currently waiting at this stage are counted here.",
        "This count identifies files waiting here now, not earlier delays.",
      ],
    },
    {
      label: "Milestone columns",
      items: [
        "The columns follow the milestones selected in Status-2.",
        "Status-4 stops at Supply Order; delivery and payment stages come later.",
      ],
    },
  ];

  if (!drill.fiscalYear) {
    return [
      {
        label: "FY",
        items: [
          "Each row shows files started/received in one FY.",
          "Click an FY to view its value bands or month-by-month breakdown.",
        ],
      },
      ...common,
    ];
  }

  if (!drill.mode) {
    return [
      {
        label: "Value Threshold",
        items: [
          "Breaks the selected FY into demand-value bands.",
          "Each file's band uses its Capital and Revenue demand values together.",
          "Use this to compare stage progress across demand sizes.",
        ],
      },
      {
        label: "Monthwise",
        items: [
          "The month labels cover the selected FY.",
          "Months are based on when files were started/received, not when an S.O. was placed or items were delivered.",
          "Click a month to see its demand-value bands.",
        ],
      },
    ];
  }

  if (drill.mode === "monthwise" && !drill.monthKey) {
    return [
      {
        label: "Month",
        items: [
          "Each row shows files started/received in that month of the selected FY.",
          "Click a month to see its demand-value bands.",
        ],
      },
      ...common,
    ];
  }

  return [
    {
      label: "Value Range",
      items: drill.monthKey
        ? [
            "Rows are value ranges for files initiated/received in the selected month.",
            "Value range uses Demand Capital + Demand Revenue for the file.",
            "Unmatched appears if a file has no matching configured value slab.",
          ]
        : [
            "Rows are value ranges for files initiated/received in the selected FY.",
            "Value range uses Demand Capital + Demand Revenue for the file.",
            "Unmatched appears if a file has no matching configured value slab.",
          ],
    },
    ...common,
  ];
}

function getStatus4DisplayRows({
  files,
  milestones,
  drill,
  thresholdRanges,
  sortKey,
  sortDirection,
  onDrillChange,
}: {
  files: FileRecord[];
  milestones: LiveStatusMilestone[];
  drill: Status4DrillState;
  thresholdRanges: Status4ThresholdRange[];
  sortKey: Status4SortKey;
  sortDirection: AnalyticsSortDirection;
  onDrillChange: (drill: Status4DrillState) => void;
}) {
  if (!drill.fiscalYear) {
    return sortStatus4Rows(
      groupStatus4RowsByKey({
        files,
        milestones,
        getKey: (file) => getFinancialYearForDate(file.receivedDate) ?? "undated",
        getLabel: (key) => (key === "undated" ? "Undated" : key),
        getSortValue: (key) =>
          key === "undated" ? Number.MAX_SAFE_INTEGER : getStatus4FySortValue(key),
        getRowMeta: (key) => ({
          fiscalYear: key,
          onLabelClick: () => onDrillChange({ fiscalYear: key }),
        }),
      }),
      sortKey,
      sortDirection,
    );
  }

  const fiscalYearFiles = files.filter(
    (file) => getStatus4FileFiscalYear(file) === drill.fiscalYear,
  );
  if (drill.mode === "monthwise" && !drill.monthKey) {
    return sortStatus4Rows(
      groupStatus4RowsByKey({
        files: fiscalYearFiles,
        milestones,
        getKey: (file) => getMonthKey(file.receivedDate) ?? "undated",
        getLabel: (key) => (key === "undated" ? "Undated" : formatMonthKeyLabel(key)),
        getSortValue: (key) => (key === "undated" ? "9999-99" : key),
        getRowMeta: (key) => ({
          fiscalYear: drill.fiscalYear,
          monthKey: key === "undated" ? undefined : key,
          onLabelClick:
            key === "undated"
              ? undefined
              : () =>
                  onDrillChange({
                    fiscalYear: drill.fiscalYear,
                    mode: "monthwise",
                    monthKey: key,
                  }),
        }),
      }),
      sortKey,
      sortDirection,
    );
  }

  const thresholdSourceFiles = drill.monthKey
    ? fiscalYearFiles.filter((file) => getMonthKey(file.receivedDate) === drill.monthKey)
    : fiscalYearFiles;
  return sortStatus4Rows(
    getStatus4ThresholdRows(
      thresholdSourceFiles,
      milestones,
      thresholdRanges,
      drill.fiscalYear,
      drill.monthKey,
    ),
    sortKey,
    sortDirection,
  );
}

type Status4ThresholdRange = {
  key: string;
  label: string;
  sortValue: number;
  minValue?: number;
  maxValue?: number;
};

function getStatus4ThresholdRanges(levels: ValueThresholdLevel[]): Status4ThresholdRange[] {
  const ranges = new Map<string, Status4ThresholdRange>();
  levels.forEach((level, index) => {
    const minValue = parseAmount(level.minValue);
    const maxValue = parseAmount(level.maxValue);
    const key = `${minValue ?? ""}:${maxValue ?? ""}`;
    if (ranges.has(key)) return;
    ranges.set(key, {
      key,
      label: formatThresholdRange(level),
      sortValue: index,
      minValue,
      maxValue,
    });
  });
  return Array.from(ranges.values());
}

function getStatus4ThresholdRows(
  files: FileRecord[],
  milestones: LiveStatusMilestone[],
  ranges: Status4ThresholdRange[],
  fiscalYear: string,
  monthKey?: string,
) {
  const rows = ranges.map((range) => {
    const rangeFiles = files.filter((file) =>
      isStatus4ValueRangeMatch(file, range.minValue, range.maxValue),
    );
    return buildStatus4TableRow({
      key: `threshold:${range.key}`,
      label: range.label,
      sortValue: range.sortValue,
      files: rangeFiles,
      milestones,
      fiscalYear,
      monthKey,
      minValue: range.minValue,
      maxValue: range.maxValue,
    });
  });
  const matchedFiles = new Set(rows.flatMap((row) => row.files.map((file) => file.id)));
  const unmatchedFiles = files.filter((file) => !matchedFiles.has(file.id));
  if (unmatchedFiles.length) {
    rows.push(
      buildStatus4TableRow({
        key: "threshold:unmatched",
        label: "Unmatched",
        sortValue: Number.MAX_SAFE_INTEGER,
        files: unmatchedFiles,
        milestones,
        fiscalYear,
        monthKey,
      }),
    );
  }
  return rows;
}

function groupStatus4RowsByKey({
  files,
  milestones,
  getKey,
  getLabel,
  getSortValue,
  getRowMeta,
}: {
  files: FileRecord[];
  milestones: LiveStatusMilestone[];
  getKey: (file: FileRecord) => string;
  getLabel: (key: string) => string;
  getSortValue: (key: string) => string | number;
  getRowMeta: (key: string) => Partial<Status4TableRow>;
}) {
  const groups = new Map<string, FileRecord[]>();
  files.forEach((file) => {
    const key = getKey(file);
    groups.set(key, [...(groups.get(key) ?? []), file]);
  });
  return Array.from(groups.entries()).map(([key, groupFiles]) =>
    buildStatus4TableRow({
      key,
      label: getLabel(key),
      sortValue: getSortValue(key),
      files: groupFiles,
      milestones,
      ...getRowMeta(key),
    }),
  );
}

function buildStatus4TableRow({
  key,
  label,
  sortValue,
  files,
  milestones,
  fiscalYear,
  monthKey,
  minValue,
  maxValue,
  onLabelClick,
}: {
  key: string;
  label: string;
  sortValue: string | number;
  files: FileRecord[];
  milestones: LiveStatusMilestone[];
  fiscalYear?: string;
  monthKey?: string;
  minValue?: number;
  maxValue?: number;
  onLabelClick?: () => void;
}): Status4TableRow {
  const metrics = Object.fromEntries(
    milestones.map((milestone) => [
      milestone.name,
      getStatus4MilestoneMetrics(files, milestone.name),
    ]),
  ) as Record<string, Status4MilestoneMetrics>;
  return {
    key,
    label,
    sortValue,
    files,
    metrics,
    total: files.length,
    fiscalYear,
    monthKey,
    minValue,
    maxValue,
    onLabelClick,
  };
}

function sortStatus4Rows(
  rows: Status4TableRow[],
  sortKey: Status4SortKey,
  sortDirection: AnalyticsSortDirection,
) {
  const direction = sortDirection === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const aValue =
      sortKey === "label"
        ? a.sortValue
        : sortKey === "total"
          ? a.total
          : (a.metrics[sortKey.slice("milestone:".length)]?.current ?? 0);
    const bValue =
      sortKey === "label"
        ? b.sortValue
        : sortKey === "total"
          ? b.total
          : (b.metrics[sortKey.slice("milestone:".length)]?.current ?? 0);
    if (typeof aValue === "number" && typeof bValue === "number") {
      return (aValue - bValue) * direction || String(a.label).localeCompare(String(b.label));
    }
    return String(aValue).localeCompare(String(bValue)) * direction;
  });
}

function getStatus4FySortValue(fiscalYear: string) {
  const match = fiscalYear.match(/\b(19\d{2}|20\d{2})\b/);
  return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER;
}

function getStatus4Milestones(milestones: LiveStatusMilestone[]) {
  const supplyOrderIndex = milestoneDefinitions.findIndex(
    (milestone) => normalizeMilestoneName(milestone.label) === "supplyorder",
  );
  return milestones.filter((milestone) => {
    const normalized = normalizeMilestoneName(milestone.name);
    const definitionIndex = milestoneDefinitions.findIndex(
      (definition) => normalizeMilestoneName(definition.label) === normalized,
    );
    return (
      definitionIndex !== -1 &&
      (supplyOrderIndex === -1 || definitionIndex <= supplyOrderIndex) &&
      normalized !== "deliveryperiod" &&
      normalized !== "advancepayment"
    );
  });
}

function getStatus4MilestoneMetrics(
  files: FileRecord[],
  milestoneName: string,
): Status4MilestoneMetrics {
  const normalized = normalizeMilestoneName(milestoneName);
  if (normalized === "financialsanction") {
    return {
      applicable: files.length,
      cleared: files.filter(isStatus4FinancialSanctionCleared).length,
      current: files.filter(isStatus4FinancialSanctionCurrent).length,
    };
  }
  if (normalized === "supplyorder") {
    return {
      applicable: files.length,
      cleared: files.filter(isStatus4SupplyOrderCleared).length,
      current: files.filter(isStatus4SupplyOrderCurrent).length,
    };
  }
  if (normalized === "billreturnedforcorrection") {
    return {
      applicable: countBillsReturnedForCorrection(files),
      cleared: countReturnedBillOrders(files, hasCompletedBillReturn),
      current: countReturnedBillsPending(files),
    };
  }
  const milestone = milestoneDefinitions.find(
    (item) => normalizeMilestoneName(item.label) === normalized,
  );
  if (!milestone) {
    return {
      applicable: files.filter((file) => !isCancelledFile(file)).length,
      cleared: getManualMilestoneCompletedCount(files, milestoneName),
      current: getLiveStatusMilestoneCount(files, milestoneName),
    };
  }
  const applicableFiles = files.filter((file) => isMilestoneApplicable(file, milestone));
  return {
    applicable: applicableFiles.length,
    cleared: applicableFiles.filter((file) => isMilestoneComplete(file, milestone)).length,
    current: getLiveStatusMilestoneCount(applicableFiles, milestoneName),
  };
}

function isStatus4FinancialSanctionCleared(file: FileRecord) {
  if (isYes(file.demandCancelled)) return false;
  return (
    normalizeCompletedMilestones(file.completedMilestones).some(
      (milestone) => normalizeMilestoneName(milestone) === "financialsanction",
    ) || rawSupplyOrders(file).some(isFinancialSanctionCompletedOrder)
  );
}

function isStatus4SupplyOrderCleared(file: FileRecord) {
  if (isYes(file.demandCancelled)) return false;
  return (
    normalizeCompletedMilestones(file.completedMilestones).some(
      (milestone) => normalizeMilestoneName(milestone) === "supplyorder",
    ) || rawSupplyOrders(file).some(hasSupplyOrderDate)
  );
}

function isStatus4FinancialSanctionCurrent(file: FileRecord) {
  if (isYes(file.demandCancelled) || isFileClosed(file)) return false;
  return countCurrentSupplyOrderMilestoneStatuses([file], "financialsanction") > 0;
}

function isStatus4SupplyOrderCurrent(file: FileRecord) {
  if (isYes(file.demandCancelled) || isFileClosed(file)) return false;
  return countCurrentSupplyOrderMilestoneStatuses([file], "supplyorder") > 0;
}

function isStatus4MetricKey(value: string): value is Status4MetricKey {
  return value === "applicable" || value === "cleared" || value === "current";
}

function isStatus4MetricMatch(file: FileRecord, milestoneName: string, metric: Status4MetricKey) {
  const normalized = normalizeMilestoneName(milestoneName);
  if (normalized === "financialsanction") {
    if (metric === "applicable") return true;
    if (metric === "cleared") return isStatus4FinancialSanctionCleared(file);
    return isStatus4FinancialSanctionCurrent(file);
  }
  if (normalized === "supplyorder") {
    if (metric === "applicable") return true;
    if (metric === "cleared") return isStatus4SupplyOrderCleared(file);
    return isStatus4SupplyOrderCurrent(file);
  }
  if (normalized === "billreturnedforcorrection") {
    if (metric === "applicable") return countBillsReturnedForCorrection([file]) > 0;
    if (metric === "cleared") return countReturnedBillOrders([file], hasCompletedBillReturn) > 0;
    return countReturnedBillsPending([file]) > 0;
  }
  const milestone = milestoneDefinitions.find(
    (item) => normalizeMilestoneName(item.label) === normalized,
  );
  if (!milestone) {
    if (metric === "applicable") return !isCancelledFile(file);
    if (metric === "cleared") return getManualMilestoneCompletedCount([file], milestoneName) > 0;
    return getLiveStatusMilestoneCount([file], milestoneName) > 0;
  }
  if (metric === "applicable") return isMilestoneApplicable(file, milestone);
  if (metric === "cleared")
    return isMilestoneApplicable(file, milestone) && isMilestoneComplete(file, milestone);
  return getLiveStatusMilestoneCount([file], milestoneName) > 0;
}

function getStatus4FileFiscalYear(file: FileRecord) {
  return getFinancialYearForDate(file.receivedDate) ?? "undated";
}

function isStatus4ValueRangeMatch(file: FileRecord, minValue?: number, maxValue?: number) {
  const capital = getInrAmount(file.valueCapital, file);
  const revenue = getInrAmount(file.valueRevenue, file);
  if (
    (minValue !== undefined || maxValue !== undefined) &&
    capital === undefined &&
    revenue === undefined
  ) {
    return false;
  }
  const value = (capital ?? 0) + (revenue ?? 0);
  if (minValue !== undefined && value < minValue) return false;
  if (maxValue !== undefined && value > maxValue) return false;
  return true;
}

function getStatus4DashboardFilter({
  milestone,
  metric,
  fiscalYear,
  monthKey,
  minValue,
  maxValue,
}: Status4SearchFilter) {
  return [
    "status4",
    encodeURIComponent(milestone),
    metric,
    encodeURIComponent(fiscalYear),
    encodeURIComponent(monthKey ?? "all"),
    minValue ?? "",
    maxValue ?? "",
  ].join(":");
}

function getStatus4SearchFocusTarget(milestone: string, metric: Status4MetricKey) {
  if (metric !== "cleared") return undefined;
  const normalized = normalizeMilestoneName(milestone);
  if (normalized === "financialsanction") return "financialsanction:completed";
  if (normalized === "supplyorder") return "supplyorder:placed";
  return undefined;
}

function formatStatus4ValueRangeTitle(minValue?: number, maxValue?: number) {
  const minLabel = minValue !== undefined ? formatLakhRangeAmount(minValue) : "0";
  if (maxValue !== undefined) return `${minLabel}-${formatLakhRangeAmount(maxValue)} L`;
  return `${minLabel} L+`;
}

function FileCategoryFilter({
  selectedCategories,
  options,
  active,
  onChange,
  onReset,
}: {
  selectedCategories: FileCategoryKey[];
  options: FileCategoryOption[];
  active: boolean;
  onChange: (category: FileCategoryKey, checked: boolean) => void;
  onReset: () => void;
}) {
  const [open, setOpen] = useState(false);
  const selectedVisibleCount = options.filter((option) =>
    selectedCategories.includes(option.key),
  ).length;
  const summary = `${selectedVisibleCount}/${options.length} selected`;

  return (
    <div className={filterLabelClass(active, "flex flex-col gap-1 text-xs text-muted-foreground")}>
      <span>File Type</span>
      <div className="flex items-center gap-1.5">
        <Popover open={open} onOpenChange={setOpen}>
          <PopoverTrigger asChild>
            <button
              type="button"
              aria-expanded={open}
              className={filterControlClass(
                active,
                "flex h-9 min-w-48 items-center justify-between gap-3 rounded-md border border-input bg-background px-2.5 text-left text-sm text-foreground outline-none focus:ring-2 focus:ring-ring/40 hover:bg-accent/60",
              )}
            >
              <span className="truncate">{summary}</span>
              <ChevronDown
                className={`size-4 shrink-0 text-muted-foreground transition-transform ${
                  open ? "rotate-180" : ""
                }`}
              />
            </button>
          </PopoverTrigger>
          <PopoverContent align="start" sideOffset={4} className="w-64 p-2">
            <div className="max-h-64 space-y-1 overflow-y-auto">
              {options.map((option) => (
                <label
                  key={option.key}
                  className="flex cursor-pointer items-center gap-2 rounded px-2 py-1.5 text-sm text-foreground hover:bg-accent"
                >
                  <input
                    type="checkbox"
                    checked={selectedCategories.includes(option.key)}
                    onChange={(event) => onChange(option.key, event.target.checked)}
                    className="size-4 shrink-0 accent-primary"
                  />
                  <span>{option.label}</span>
                </label>
              ))}
            </div>
          </PopoverContent>
        </Popover>
        <button
          type="button"
          onClick={onReset}
          disabled={!active}
          title="Reset File Type to all options"
          aria-label="Reset File Type to all options"
          className="inline-flex size-9 shrink-0 items-center justify-center rounded-md border border-input bg-background text-foreground hover:bg-accent disabled:cursor-not-allowed disabled:opacity-50"
        >
          <RotateCcw className="size-4" />
        </button>
      </div>
    </div>
  );
}

