  coBiddingFirms: CoBiddingFirmRow[];
  coBiddingTenders: CoBiddingTenderRow[];
  selectedPartnerName: string;
  loading: boolean;
  onOpenAll: () => void;
  onExport: (format: "pdf" | "excel") => void;
