function withAnalyticsRanks(rows: Array<Record<string, number | string>>) {
  return rows.map((row, index) => ({ ...row, rank: index + 1 }));
}

function sortAnalyticsRows(
  rows: Array<Record<string, number | string>>,
  direction: AnalyticsSortDirection,
) {
  return direction === "desc" ? rows : [...rows].reverse();
}

function sortAnalyticsRowsByMetric(
  rows: Array<Record<string, number | string>>,
  metric: string,
  direction: AnalyticsSortDirection,
) {
  return [...rows].sort((left, right) => {
    const difference = Number(left[metric] ?? 0) - Number(right[metric] ?? 0);
    if (difference !== 0) return direction === "desc" ? -difference : difference;
    return String(left.name ?? "").localeCompare(String(right.name ?? ""));
  });
}

function sortIndentorValueRows(
  rows: Array<Record<string, number | string>>,
  sortKey: IndentorValueSortKey,
  direction: AnalyticsSortDirection,
) {
  return [...rows].sort((a, b) => {
    const left = Number(a[sortKey] ?? 0);
    const right = Number(b[sortKey] ?? 0);
    const diff = direction === "desc" ? right - left : left - right;
    if (diff !== 0) return diff;
    const leftTotal = Number(a.value ?? 0);
    const rightTotal = Number(b.value ?? 0);
    const totalDiff = rightTotal - leftTotal;
    if (totalDiff !== 0) return totalDiff;
    return String(a.name ?? "").localeCompare(String(b.name ?? ""));
  });
}

function sortMilestoneClearingRows(
  rows: Array<Record<string, number | string>>,
  mode: MilestoneClearingViewMode,
  _direction: AnalyticsSortDirection,
) {
  if (mode === "ranking") return sortAnalyticsRows(rows, _direction);
  const sortedRows = [...rows].sort(
    (a, b) =>
      getMilestoneClearingSequence(a) - getMilestoneClearingSequence(b) ||
      String(a.name ?? "").localeCompare(String(b.name ?? "")),
  );
  return sortedRows;
}

function getMilestoneClearingDisplayRows(
  rows: Array<Record<string, number | string>>,
  mode: MilestoneClearingViewMode,
) {
  if (mode === "ranking") return rows;
  const rowsByName = new Map(
    rows.map((row) => [normalizeAnalyticsName(String(row.name ?? "")), row] as const),
  );
  return milestoneClearingDefinitions.flatMap((definition, index) => {
    const row = rowsByName.get(normalizeAnalyticsName(definition.name));
    if (!row || Number(row.sampleSize ?? 0) <= 0) return [];
    return [
      {
        ...row,
        sortOrder: Number(row.sortOrder ?? index),
      },
    ];
  });
}

function getMilestoneClearingSequence(row: Record<string, number | string>) {
  const sortOrder = Number(row.sortOrder);
  if (Number.isFinite(sortOrder)) return sortOrder;
  return getMilestoneClearingDefinitionOrder(String(row.name ?? ""));
}

function getMilestoneClearingDefinitionOrder(name: string) {
  const normalizedName = normalizeAnalyticsName(name);
  const index = milestoneClearingDefinitions.findIndex(
    (definition) => normalizeAnalyticsName(definition.name) === normalizedName,
  );
  return index === -1 ? Number.MAX_SAFE_INTEGER : index;
}

function withAssignedDivisionRows(
  rows: Array<Record<string, number | string>>,
  assignedDivisionNames: string[],
) {
  if (!assignedDivisionNames.length) return rows;
  const existingNames = new Set(rows.map((row) => normalizeAnalyticsName(String(row.name ?? ""))));
  const assignedRows: Array<Record<string, number | string>> = assignedDivisionNames
    .filter((name) => !existingNames.has(normalizeAnalyticsName(name)))
    .map((name) => ({
      name,
      count: 0,
      averageDays: 0,
      sampleSize: 0,
      allocatedCapital: 0,
      allocatedRevenue: 0,
      allocatedTotal: 0,
      intendedCapital: 0,
      intendedRevenue: 0,
      intendedTotal: 0,
      bookedCapital: 0,
      bookedRevenue: 0,
      bookedTotal: 0,
      committedCapital: 0,
      committedRevenue: 0,
      committedTotal: 0,
    }));
  return assignedRows.length ? [...rows, ...assignedRows] : rows;
}

function getAssignedDivisionNames(divisionIds: string[] | undefined, divisions: Division[]) {
  if (!divisionIds?.length) return [];
  const assignedIds = new Set(divisionIds);
  return divisions
    .filter((division) => assignedIds.has(division.id))
    .map((division) => division.name)
    .filter(Boolean);
}

function normalizeAnalyticsName(value: string) {
  return value.trim().toLowerCase();
}

function getAnalyticsPagination(
  rows: Array<Record<string, number | string>>,
  limit: AnalyticsResultLimitKey,
  requestedPage: number,
) {
  const pageSize = limit === "all" ? rows.length || 1 : Number(limit);
  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  const page = Math.min(Math.max(1, requestedPage), totalPages);
  const start = (page - 1) * pageSize;
  const end = Math.min(start + pageSize, rows.length);
  return {
    rows: limit === "all" ? rows : rows.slice(start, end),
    page,
    pageSize,
    total: rows.length,
    totalPages,
    start: rows.length ? start + 1 : 0,
    end,
    pageNumbers: getAnalyticsPaginationPages(page, totalPages),
  };
}

function getAnalyticsPaginationPages(currentPage: number, totalPages: number) {
  const visible = Math.min(5, totalPages);
  const half = Math.floor(visible / 2);
  let startPage = Math.max(1, currentPage - half);
  const lastPage = Math.min(totalPages, startPage + visible - 1);
  startPage = Math.max(1, lastPage - visible + 1);
  return Array.from({ length: lastPage - startPage + 1 }, (_, index) => startPage + index);
}

function getAnalyticsSearchTarget(
  panelKey: AnalyticsPanelKey,
  row: Record<string, number | string>,
  columnKey: string,
  context?: AnalyticsSearchContext,
): AnalyticsSearchTarget | undefined {
  const name = String(row.name ?? row.range ?? row.fileRef ?? "").trim();
  if (
    !name ||
    columnKey === "rank" ||
    (columnKey === "name" && panelKey !== "cncSummary" && panelKey !== "preBidMeetings") ||
    columnKey === "range"
  )
    return undefined;
  if (columnKey === "name" && Number(row.monthDrilldown ?? 0) === 1) return undefined;

  if (panelKey === "divisionFiles" && columnKey === "fileCount") {
    return { division: name, focusSection: "File details", focusTarget: "division" };
  }
  if (panelKey === "divisionFiles" && columnKey === "soCount") {
    return {
      division: name,
      dashboardFilter: "supplyOrders",
      focusSection: "Supply order and payment",
      focusTarget: "supplyorder:any",
    };
  }
  if (panelKey === "divisionTurnaround" && columnKey === "sampleSize") {
    return {
      dashboardFilter: "divisionTurnaroundSample",
      division: name,
      focusSection: "Supply order and payment",
      focusTarget: "supplyorder:any",
    };
  }
  if (panelKey === "paymentPending" && columnKey === "count") {
    return {
      dashboardFilter: "analyticsPaymentPending",
      division: name,
      focusSection: "Supply order and payment",
      focusTarget: "payment:pending",
    };
  }
  if (panelKey === "preBidMeetings") {
    const fiscalYear = String(row.fiscalYear ?? "").trim();
    if (/^\d{4}-\d{2}$/.test(fiscalYear)) {
      const filterByColumn: Record<string, string> = {
        count: `preBidMeetingCombinedFy:all:${fiscalYear}`,
        preBidDue: `preBidMeetingFy:due:${fiscalYear}`,
        preBidCompleted: `preBidMeetingFy:completed:${fiscalYear}`,
        refloatPreBidDue: `refloatPreBidMeetingFy:due:${fiscalYear}`,
        refloatPreBidCompleted: `refloatPreBidMeetingFy:completed:${fiscalYear}`,
      };
      const dashboardFilter = filterByColumn[columnKey];
      return dashboardFilter ? { dashboardFilter, focusSection: "Bidding details" } : undefined;
    }
    const monthKey = String(row.monthKey ?? row.name ?? "").trim();
    if (!/^\d{4}-\d{2}$/.test(monthKey)) return undefined;
    const filterByColumn: Record<string, string> = {
      name: `preBidMeetingCombined:all:${monthKey}`,
      count: `preBidMeetingCombined:all:${monthKey}`,
      preBidDue: `preBidMeeting:due:${monthKey}`,
      preBidCompleted: `preBidMeeting:completed:${monthKey}`,
      refloatPreBidDue: `refloatPreBidMeeting:due:${monthKey}`,
      refloatPreBidCompleted: `refloatPreBidMeeting:completed:${monthKey}`,
    };
    const dashboardFilter = filterByColumn[columnKey];
    return dashboardFilter ? { dashboardFilter, focusSection: "Bidding details" } : undefined;
  }
  if (
    panelKey === "tcecStatus" &&
    (columnKey === "reviewed" || columnKey === "signed" || columnKey === "pending")
  ) {
    const stage = String(row.stage ?? "pre") === "post" ? "post" : "pre";
    const fiscalYear = String(row.fiscalYear ?? context?.selectedTcecFiscalYear ?? "").trim();
    if (/^\d{4}-\d{2}$/.test(fiscalYear)) {
      const committee = String(row.name ?? "").trim();
      const isCommitteeRow = Boolean(
        row.committee === undefined && committee && committee !== fiscalYear,
      );
      return {
        dashboardFilter: isCommitteeRow
          ? getTcecStatusFiscalYearDashboardFilter(stage, columnKey, fiscalYear, committee)
          : getTcecStatusFiscalYearDashboardFilter(stage, columnKey, fiscalYear),
        focusSection: "TCEC block",
      };
    }
    return {
      dashboardFilter: getTcecStatusDashboardFilter(stage, columnKey, name),
      focusSection: "TCEC block",
    };
  }
  if (panelKey === "cncSummary" && isCncSummaryMetric(columnKey)) {
    const fiscalYear = String(row.fiscalYear ?? "").trim();
    if (/^\d{4}-\d{2}$/.test(fiscalYear)) {
      if (columnKey === "name") return undefined;
      return {
        dashboardFilter: getCncSummaryFiscalYearDashboardFilter(columnKey, fiscalYear),
        focusSection: "Approval block",
      };
    }
    const cncDate = String(row.cncDate ?? row.name ?? "").trim();
    if (!cncDate) return undefined;
    return {
      dashboardFilter: getCncSummaryDashboardFilter(columnKey, cncDate),
      focusSection: "Approval block",
    };
  }
  if (panelKey === "topFirms" && columnKey === "value") {
    return {
      analyticsType: "firm",
      analyticsNames: [name],
      focusSection: "Firm details",
    };
  }
  if (panelKey === "firmAnalysis") {
    const firm = String(row.name ?? "").trim();
    if (!firm || columnKey === "name") return undefined;
    const expression = String(row.selectedRolesExpression ?? "").trim();
    if (columnKey === "selectedRoles" && expression) {
      return {
        dashboardFilter: `firmAnalysis:expr:${expression}:${encodeURIComponent(firm)}`,
        focusSection: "Firm details",
      };
    }
  }
  if (panelKey === "indentorsByFiles" && columnKey === "fileCount") {
    return {
      analyticsType: "indentor",
      analyticsNames: [name],
      focusSection: "File details",
      focusTarget: "indentor",
    };
  }
  if (panelKey === "indentorsByFiles" && columnKey === "soCount") {
    return {
      analyticsType: "indentor",
      analyticsNames: [name],
      dashboardFilter: "supplyOrders",
      focusSection: "Supply order and payment",
      focusTarget: "supplyorder:any",
    };
  }
  if (
    panelKey === "indentorsByValue" &&
    (columnKey === "capital" || columnKey === "revenue" || columnKey === "value")
  ) {
    return {
      analyticsType: "indentor",
      analyticsNames: [name],
      capitalOnly: columnKey === "capital",
      revenueOnly: columnKey === "revenue",
      focusSection: "File details",
      focusTarget: "indentor",
    };
  }
  if (panelKey === "biddingMode" && columnKey === "count") {
    return {
      dashboardFilter: `mode:${name.toUpperCase()}`,
      focusSection: "Bidding details",
    };
  }
  if (panelKey === "fileValueThresholds") {
    if (
      columnKey === "count" ||
      columnKey === "capitalCount" ||
      columnKey === "revenueCount" ||
      columnKey === "capital" ||
      columnKey === "revenue" ||
      columnKey === "value" ||
      columnKey === "countContribution" ||
      columnKey === "capitalCountContribution" ||
      columnKey === "revenueCountContribution" ||
      columnKey === "capitalContribution" ||
      columnKey === "revenueContribution" ||
      columnKey === "valueContribution"
    ) {
      const isSupplyOrder = row.source === "supplyOrder";
      const metricByColumn: Record<string, "capital" | "revenue" | "total" | undefined> = {
        capitalCount: "capital",
        capitalCountContribution: "capital",
        capital: "capital",
        capitalContribution: "capital",
        revenueCount: "revenue",
        revenueCountContribution: "revenue",
        revenue: "revenue",
        revenueContribution: "revenue",
      };
      const metric = metricByColumn[columnKey];
      const filterPrefix = isSupplyOrder ? "soValueThreshold" : "valueThreshold";
      return {
        dashboardFilter: `${filterPrefix}:${encodeURIComponent(name)}${metric ? `:${metric}` : ""}`,
        focusSection: isSupplyOrder ? "Supply order and payment" : "File details",
        focusTarget: isSupplyOrder
          ? "supplyorder:any"
          : metric === "revenue"
            ? "valueRevenue"
            : "valueCapital",
      };
    }
    return undefined;
  }
  if (panelKey === "suspectedAnomaly" && columnKey !== "action" && columnKey !== "rank") {
    const fileId = String(row.fileId ?? "").trim();
    return fileId
      ? {
          dashboardFilter: `anomalyFile:${encodeURIComponent(fileId)}`,
          ...getSuspectedAnomalySearchFocus(row),
        }
      : undefined;
  }
  if (panelKey === "milestoneClearingTable" && columnKey === "fileCount") {
    const target = withMilestoneClearingSearchFilters(
      getMilestoneClearingSearchTarget(name),
      context,
    );
    return target
      ? { ...target, ...getMilestoneClearingSearchFocus(name, target) }
      : undefined;
  }
  return undefined;
}

type AnalyticsSearchContext = {
  milestoneClearingMode: string;
  milestoneClearingValueThreshold: MilestoneClearingThresholdFilter;
  milestoneClearingPath: "all" | "tcec" | "nonTcec";
  milestoneClearingDivision: string;
  milestoneClearingFileType: string;
  milestoneClearingGem: "all" | "gem" | "nonGem";
  milestoneClearingRefloat: "all" | "yes" | "no";
  milestoneClearingWorkflowFlags: { highValue: string; ad: string; rqa: string; ifa: string };
  milestoneClearingPreCommittee: string;
  milestoneClearingPostCommittee: string;
  milestoneClearingFileQuery: string;
  milestoneClearingDemandFy: string;
  milestoneClearingDemandMonth: string;
  valueThresholdLevels: ValueThresholdLevel[];
  selectedTcecFiscalYear?: string;
};

function withMilestoneClearingSearchFilters(
  target: AnalyticsSearchTarget | undefined,
  context: AnalyticsSearchContext | undefined,
): AnalyticsSearchTarget | undefined {
  if (!target) return target;
  const extraDashboardFilters: string[] = [...(target.extraDashboardFilters ?? [])];
  if (!context) {
    return { ...target, milestoneClearingScope: true };
  }
  if (context.milestoneClearingValueThreshold === "unmatched") {
    extraDashboardFilters.push("valueThreshold:Unmatched");
  } else if (context.milestoneClearingValueThreshold.startsWith("level:")) {
    const levelId = context.milestoneClearingValueThreshold.slice("level:".length).trim();
    if (levelId) extraDashboardFilters.push(`valueThresholdId:${levelId}`);
  }
  if (context.milestoneClearingPath !== "all") {
    extraDashboardFilters.push(`attribute:tcec:${context.milestoneClearingPath === "tcec" ? "yes" : "no"}`);
  }
  if (context.milestoneClearingDivision !== "all") {
    extraDashboardFilters.push(`division:${encodeURIComponent(context.milestoneClearingDivision)}`);
  }
  if (context.milestoneClearingFileType !== "all") {
    extraDashboardFilters.push(`fileType:${encodeURIComponent(context.milestoneClearingFileType)}`);
  }
  if (context.milestoneClearingGem !== "all") {
    extraDashboardFilters.push(`attribute:gem:${context.milestoneClearingGem === "gem" ? "yes" : "no"}`);
  }
  if (context.milestoneClearingRefloat !== "all") {
    extraDashboardFilters.push(`attribute:refloat:${context.milestoneClearingRefloat}`);
  }
  for (const [key, value] of Object.entries(context.milestoneClearingWorkflowFlags)) {
    if (value !== "all") extraDashboardFilters.push(`attribute:${key}:${value}`);
  }
  if (context.milestoneClearingPath === "tcec") {
    if (context.milestoneClearingPreCommittee !== "all") {
      extraDashboardFilters.push(`fileField:preTcecCommitteeNo:${encodeURIComponent(context.milestoneClearingPreCommittee)}`);
    }
    if (context.milestoneClearingPostCommittee !== "all") {
      extraDashboardFilters.push(`fileField:postTcecCommitteeNumber,refloatPostTcecCommitteeNo:${encodeURIComponent(context.milestoneClearingPostCommittee)}`);
    }
  }
  if (context.milestoneClearingFileQuery !== "all") {
    extraDashboardFilters.push(`fileIds:${encodeURIComponent(context.milestoneClearingFileQuery)}`);
  }
  if (context.milestoneClearingDemandFy !== "all") {
    extraDashboardFilters.push(`fileInflowYear:${context.milestoneClearingDemandFy}`);
  }
  if (context.milestoneClearingDemandMonth !== "all") {
    extraDashboardFilters.push(`fileInflowMonth:${context.milestoneClearingDemandMonth}`);
  }
  const includeModes =
    context.milestoneClearingMode && context.milestoneClearingMode !== "all"
      ? [context.milestoneClearingMode]
      : target.includeModes;
  return {
    ...target,
    milestoneClearingScope: true,
    extraDashboardFilters: extraDashboardFilters.length ? extraDashboardFilters : undefined,
    includeModes,
  };
}

type AnalyticsTotalSearchContext = {
  countValueAnalysisMode: CountValueAnalysisMode;
  selectedPreBidFiscalYear: string;
  selectedTcecFiscalYear: string;
  selectedCncFiscalYear: string;
  tcecStatusStage: TcecStatusStage;
};

function getAnalyticsTotalSearchTarget(
  panelKey: AnalyticsPanelKey,
  columnKey: string,
  context: AnalyticsTotalSearchContext,
): AnalyticsSearchTarget | undefined {
  if (columnKey === "rank" || columnKey === "name" || columnKey === "range") return undefined;
  if (panelKey === "fileValueThresholds") {
    const isSupplyOrder =
      context.countValueAnalysisMode === "soValue" ||
      context.countValueAnalysisMode === "countSoValue" ||
      context.countValueAnalysisMode === "countSoValuePercent";
    const metricByColumn: Record<string, string> = {
      count: "total",
      countContribution: "total",
      capitalCount: "capital",
      capitalCountContribution: "capital",
      revenueCount: "revenue",
      revenueCountContribution: "revenue",
      capital: "capital",
      revenue: "revenue",
      value: "total",
      valueContribution: "total",
    };
    const metric = metricByColumn[columnKey];
    return metric
      ? {
          dashboardFilter: `${isSupplyOrder ? "soValueThresholdTotal" : "valueThresholdTotal"}:${metric}`,
          focusSection: isSupplyOrder ? "Supply order and payment" : "File details",
          focusTarget: isSupplyOrder
            ? "supplyorder:any"
            : metric === "revenue"
              ? "valueRevenue"
              : "valueCapital",
        }
      : undefined;
  }
  if (panelKey === "preBidMeetings") {
    const fiscalYear = context.selectedPreBidFiscalYear;
    const filterByColumn: Record<string, string> = fiscalYear
      ? {
          count: `preBidMeetingCombinedFy:all:${fiscalYear}`,
          preBidDue: `preBidMeetingFy:due:${fiscalYear}`,
          preBidCompleted: `preBidMeetingFy:completed:${fiscalYear}`,
          refloatPreBidDue: `refloatPreBidMeetingFy:due:${fiscalYear}`,
          refloatPreBidCompleted: `refloatPreBidMeetingFy:completed:${fiscalYear}`,
        }
      : {
          count: "preBidMeetingCombined:all",
          preBidDue: "preBidMeeting:due",
          preBidCompleted: "preBidMeeting:completed",
          refloatPreBidDue: "refloatPreBidMeeting:due",
          refloatPreBidCompleted: "refloatPreBidMeeting:completed",
        };
    const dashboardFilter = filterByColumn[columnKey];
    return dashboardFilter ? { dashboardFilter, focusSection: "Bidding details" } : undefined;
  }
  if (
    panelKey === "tcecStatus" &&
    (columnKey === "reviewed" || columnKey === "signed" || columnKey === "pending")
  ) {
    return {
      dashboardFilter: getTcecStatusFiscalYearDashboardFilter(
        context.tcecStatusStage,
        columnKey,
        context.selectedTcecFiscalYear || "all",
      ),
      focusSection: "TCEC block",
    };
  }
  if (panelKey === "cncSummary" && isCncSummaryMetric(columnKey)) {
    return {
      dashboardFilter: getCncSummaryFiscalYearDashboardFilter(
        columnKey,
        context.selectedCncFiscalYear || "all",
      ),
      focusSection: "Approval block",
    };
  }
  return undefined;
}

function getTcecMeetingSearchTarget(
  stage: TcecStatusStage,
  row: Record<string, number | string>,
  columnKey: string,
): AnalyticsSearchTarget | undefined {
  if (
    columnKey !== "name" &&
    columnKey !== "reviewed" &&
    columnKey !== "signed" &&
    columnKey !== "pending"
  ) {
    return undefined;
  }
  const committee = String(row.committee ?? "").trim();
  const meetingDate = String(row.meetingDate ?? row.name ?? "").trim();
  if (!committee || !meetingDate) return undefined;
  const metric = columnKey === "name" ? "reviewed" : columnKey;
  return {
    dashboardFilter: getTcecStatusDashboardFilter(stage, metric, committee, meetingDate),
    focusSection: "TCEC block",
  };
}

function getTcecCommitteeTotalSearchTarget(
  stage: TcecStatusStage,
  committee: string,
  fiscalYear: string,
  columnKey: string,
): AnalyticsSearchTarget | undefined {
  if (columnKey !== "reviewed" && columnKey !== "signed" && columnKey !== "pending") {
    return undefined;
  }
  const cleanCommittee = committee.trim();
  if (!cleanCommittee) return undefined;
  return {
    dashboardFilter: fiscalYear
      ? getTcecStatusFiscalYearDashboardFilter(stage, columnKey, fiscalYear, cleanCommittee)
      : getTcecStatusDashboardFilter(stage, columnKey, cleanCommittee),
    focusSection: "TCEC block",
  };
}

function getSuspectedAnomalySearchFocus(row: Record<string, number | string>) {
  const block = normalizeMilestoneName(String(row.block ?? ""));
  const rule = normalizeMilestoneName(String(row.rule ?? ""));
  const previousField = normalizeMilestoneName(String(row.previousField ?? ""));
  const laterField = normalizeMilestoneName(String(row.laterField ?? ""));
  const source = `${block} ${rule} ${previousField} ${laterField}`;

  if (block === "datacompleteness") {
    return { focusSection: "File details" };
  }
  if (
    block === "bidding" ||
    block === "prebidmeeting" ||
    block === "refloat" ||
    block === "refloatprebidmeeting"
  ) {
    return { focusSection: "Bidding details" };
  }
  if (block === "tcec") return { focusSection: "TCEC block" };
  if (block === "scrutiny" || block === "control") {
    return { focusSection: "Scrutiny and control" };
  }
  if (block === "closure") {
    return { focusSection: "Milestones", focusMilestone: "File Closed" };
  }
  if (
    block === "highvalue" ||
    block === "ad" ||
    block === "rqa" ||
    block === "ifa" ||
    block === "cfa" ||
    block === "cnc"
  ) {
    return { focusSection: "Approval block" };
  }
  if (block === "cancellation" && !source.includes("so")) {
    return { focusSection: "File details" };
  }

  const supplyOrderTarget = getSuspectedAnomalySupplyOrderFocusTarget(source);
  if (supplyOrderTarget) {
    return { focusSection: "Supply order and payment", focusTarget: supplyOrderTarget };
  }
  if (
    source.includes("division") ||
    source.includes("description") ||
    source.includes("indentor")
  ) {
    return { focusSection: "File details" };
  }
  return { focusSection: "Timeline" };
}

function getSuspectedAnomalySupplyOrderFocusTarget(source: string) {
  const paddedSource = ` ${source} `;
  if (source.includes("psbpwb") || source.includes("combinedbg")) return "psbpwb:any";
  if (source.includes("pwb")) return "pwb:any";
  if (source.includes("psb")) return "psb:any";
  if (source.includes("bankguarantee") || source.includes("bg")) return "securitybg:any";
  if (source.includes("deliveryperiod") || source.includes("reviseddp") || source.includes("dp")) {
    return "deliveryperiod:any";
  }
  if (source.includes("stagedelivery")) return "stagedelivery:any";
  if (source.includes("stagepayment")) return "stagepayment:any";
  if (source.includes("advancepayment")) return "advancepayment:yes";
  if (source.includes("jobcompletion")) return "jobcompletion:any";
  if (source.includes("delivery") || source.includes("materialreceipt")) return "delivery:any";
  if (source.includes("irpreparation")) return "irpreparation:any";
  if (source.includes("irreceipt") || paddedSource.includes(" ir ")) return "irreceipt:any";
  if (source.includes("billpreparation")) return "billpreparation:any";
  if (source.includes("billsentforpayment")) return "billsentforpayment:any";
  if (source.includes("actualpayment")) return "actualpayment:yes";
  if (source.includes("payment")) return "payment:any";
  if (source.includes("financialsanction")) return "financialsanction:any";
  if (source.includes("firmtype")) return "firmtype:any";
  if (source.includes("firm") || source.includes("supplyorder") || source.includes("so")) {
    return "supplyorder:any";
  }
  return undefined;
}

function getCncSummaryDashboardFilter(metric: string, cncDate: string) {
  return `cncSummary:${encodeURIComponent(metric)}:${encodeURIComponent(cncDate)}`;
}

function getCncSummaryFiscalYearDashboardFilter(metric: string, fiscalYear: string) {
  return `cncSummaryFy:${encodeURIComponent(metric)}:${encodeURIComponent(fiscalYear)}`;
}

function isCncSummaryMetric(value: string) {
  return (
    value === "name" ||
    value === "reviewed" ||
    value === "approved" ||
    value === "financialSanctionSigned" ||
    value === "supplyOrderPlaced" ||
    value === "approvalPending" ||
    value === "financialSanctionPending" ||
    value === "supplyOrderPending"
  );
}

function getTcecStatusDashboardFilter(
  stage: string,
  metric: string,
  committee: string,
  meetingDate?: string,
) {
  return [
    "tcecStatus",
    encodeURIComponent(stage),
    encodeURIComponent(metric),
    encodeURIComponent(committee),
    meetingDate ? encodeURIComponent(meetingDate) : undefined,
  ]
    .filter((part): part is string => Boolean(part))
    .join(":");
}

function getTcecStatusFiscalYearDashboardFilter(
  stage: string,
  metric: string,
  fiscalYear: string,
  committee?: string,
) {
  return [
    "tcecStatusFy",
    encodeURIComponent(stage),
    encodeURIComponent(metric),
    encodeURIComponent(fiscalYear),
    committee ? encodeURIComponent(committee) : undefined,
  ]
    .filter((part): part is string => Boolean(part))
    .join(":");
}

function getFinance1DrillFocus(
  key: string,
  section: string,
  metric: string,
): Pick<AnalyticsSearchTarget, "focusSection" | "focusMilestone" | "focusTarget"> {
  const normalizedKey = key.toLowerCase();
  const normalizedSection = section.toLowerCase();
  const normalizedMetric = metric.toLowerCase();

  if (normalizedKey.includes("advancepaid")) {
    return { focusSection: "Supply order and payment", focusTarget: "advancepayment:paid" };
  }
  if (normalizedKey.includes("supplementarypaid")) {
    return { focusSection: "Supply order and payment", focusTarget: "supplementarybill:paid" };
  }
  if (normalizedKey.includes("billssent")) {
    return { focusSection: "Supply order and payment", focusTarget: "billsentforpayment:completed" };
  }
  if (normalizedKey.includes("paymentpaid") || normalizedKey.includes("selectedbillspaid")) {
    return { focusSection: "Supply order and payment", focusTarget: "payment:completed" };
  }
  if (normalizedKey.includes("paymentduebutbillnotsubmitted")) {
    return { focusSection: "Supply order and payment", focusTarget: "billpreparation:pending" };
  }
  if (normalizedKey.includes("paymentdue") || normalizedKey.includes("paymentstillunpaid")) {
    return { focusSection: "Supply order and payment", focusTarget: "payment:pending" };
  }
  if (normalizedKey.includes("socancelledlater")) {
    return { focusSection: "Supply order and payment", focusTarget: "socancelled:yes" };
  }
  if (normalizedKey.includes("soplaced")) {
    return { focusSection: "Supply order and payment", focusTarget: "supplyorder:placed" };
  }
  if (normalizedKey.includes("socompletedlater")) {
    return {
      focusSection: "Supply order and payment",
      focusTarget: "delivery:completed|jobcompletion:completed",
    };
  }
  if (normalizedKey.includes("yearendliabilitypaidlater")) {
    return { focusSection: "Supply order and payment", focusTarget: "payment:completed" };
  }
  if (normalizedKey.includes("yearendliability")) {
    return { focusSection: "Supply order and payment", focusTarget: "payment:pending" };
  }
  if (normalizedKey.includes("selectedbillsstoppednfa")) {
    return { focusSection: "Supply order and payment", focusTarget: "payment:pending" };
  }
  if (normalizedKey.includes("deliverypendingcompletedlater")) {
    return { focusSection: "Supply order and payment", focusTarget: "delivery:completed" };
  }
  if (normalizedKey.includes("jobcompletionpendingcompletedlater")) {
    return { focusSection: "Supply order and payment", focusTarget: "jobcompletion:completed" };
  }
  if (normalizedKey.includes("materialreceiptpending")) {
    return { focusSection: "Supply order and payment", focusTarget: "delivery:pending" };
  }
  if (normalizedKey.includes("jobcompletionpending")) {
    return { focusSection: "Supply order and payment", focusTarget: "jobcompletion:pending" };
  }
  if (normalizedKey.includes("filesclosed")) {
    return { focusSection: "Milestones", focusMilestone: "File Closed" };
  }
  if (normalizedKey.includes("filegroup")) {
    return { focusSection: "File details", focusTarget: "receivedDate" };
  }
  if (normalizedKey.includes("closed") || normalizedMetric.includes("file closed")) {
    return { focusSection: "Milestones", focusMilestone: "File Closed" };
  }
  if (normalizedKey.includes("cancelled") || normalizedMetric.includes("cancelled")) {
    return { focusSection: "File details", focusTarget: "demandCancelled" };
  }
  if (normalizedKey.includes("booked") || normalizedMetric.includes("controlled done")) {
    return { focusSection: "Scrutiny and control", focusTarget: "immsDate" };
  }
  if (normalizedKey.includes("intended") || normalizedMetric.includes("controlled by")) {
    return { focusSection: "Scrutiny and control", focusTarget: "imms" };
  }
  if (normalizedKey.includes("billssubmitted") || normalizedMetric.includes("bill sent")) {
    return { focusSection: "Supply order and payment", focusTarget: "billsentforpayment:completed" };
  }
  if (normalizedKey.includes("paymentduebutbillnotsubmitted")) {
    return { focusSection: "Supply order and payment", focusTarget: "billpreparation:pending" };
  }
  if (normalizedKey.includes("advancepending")) {
    return { focusSection: "Supply order and payment", focusTarget: "advancepayment:pending" };
  }
  if (normalizedKey.includes("deliveryjobdone")) {
    return {
      focusSection: "Supply order and payment",
      focusTarget: "delivery:completed|jobcompletion:completed",
    };
  }
  if (normalizedKey.includes("deliveryjobpending")) {
    return {
      focusSection: "Supply order and payment",
      focusTarget: "delivery:pending|jobcompletion:pending",
    };
  }
  if (
    normalizedKey.includes("committed") ||
    normalizedKey.includes("soplaced") ||
    normalizedKey.includes("withso") ||
    normalizedKey.includes("soplacedlater") ||
    normalizedMetric.includes("s.o. placed") ||
    normalizedMetric.includes("committed")
  ) {
    return { focusSection: "Supply order and payment", focusTarget: "supplyorder:placed" };
  }
  if (normalizedKey.includes("advance")) {
    return { focusSection: "Supply order and payment", focusTarget: "advancepayment:pending" };
  }
  if (normalizedKey.includes("paymentdue") || normalizedKey.includes("unpaid")) {
    return { focusSection: "Supply order and payment", focusTarget: "payment:pending" };
  }
  if (normalizedKey.includes("paid") || normalizedKey.includes("paymentmade")) {
    return { focusSection: "Supply order and payment", focusTarget: "payment:completed" };
  }
  if (normalizedKey.includes("delivery") || normalizedMetric.includes("delivery")) {
    return { focusSection: "Supply order and payment", focusTarget: "delivery:pending" };
  }
  if (normalizedSection.includes("firm type")) {
    return { focusSection: "Supply order and payment", focusTarget: "firmtype:any" };
  }
  if (normalizedSection.includes("file type") || normalizedSection.includes("file group")) {
    return { focusSection: "File details", focusTarget: "fileType" };
  }
  if (normalizedKey.includes("active") || normalizedKey.includes("stillpending")) {
    return { focusSection: "File details" };
  }
  return { focusSection: "Timeline" };
}

function getMilestoneClearingSearchTarget(name: string): AnalyticsSearchTarget | undefined {
  const normalized = normalizeMilestoneName(name);
  if (normalized === "bidding") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:bidding",
      focusSection: "Bidding details",
    };
  }
  if (normalized === "nontcectechnicalevaluation") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:nonTcecTechnicalEvaluation",
      focusSection: "Supply order and payment",
      focusTarget: "financialSanctionDate",
    };
  }
  if (normalized === "irpreparation" || normalized === "irreceipt") {
    const label = normalized === "irpreparation" ? "IR Preparation" : "IR Receipt";
    return {
      dashboardFilter: `manualMilestoneCompleted:${label}`,
      focusSection: "Supply order and payment",
      focusTarget: `${normalized}:completed`,
    };
  }
  if (normalized === "supplyorder") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:supplyOrder",
      focusSection: "Supply order and payment",
      focusTarget: "financialSanctionDate",
    };
  }
  if (normalized === "gemundertaking") {
    return {
      dashboardFilter: "gemUndertaking:completed",
      focusSection: "Bidding details",
      focusTarget: "gemUndertakingDate",
    };
  }
  if (normalized === "billpreparation") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:billPreparation",
      focusSection: "Supply order and payment",
      focusTarget: "billpreparation:completed",
    };
  }
  if (normalized === "billsentforpayment" || normalized === "billsenttocda") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:billSentForPayment",
      focusSection: "Supply order and payment",
      focusTarget: "billsentforpayment:completed",
    };
  }
  if (normalized === "delivery") return { dashboardFilter: "deliveryCompleted" };
  if (normalized === "paymentcyclepcda" || normalized === "paymentaftersubmission") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:payment",
      focusSection: "Supply order and payment",
      focusTarget: "payment:completed",
    };
  }
  if (normalized === "paymentcycleasl" || normalized === "paymentbeforesubmission") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:paymentPreSubmission",
      focusSection: "Supply order and payment",
      focusTarget: "billsentforpayment:completed",
    };
  }
  if (normalized === "paymentaslpcda" || normalized === "cumulativepayment") {
    return {
      dashboardFilter: "analyticsMilestoneClearing:paymentCumulative",
      focusSection: "Supply order and payment",
      focusTarget: "payment:completed",
    };
  }
  const milestone = milestoneDefinitions.find(
    (item) => normalizeMilestoneName(item.label) === normalized,
  );
  if (milestone) return { dashboardFilter: `milestoneCleared:${milestone.key}` };
  return undefined;
}

function getMilestoneClearingSearchFocus(
  name: string,
  target: AnalyticsSearchTarget,
): Pick<AnalyticsSearchTarget, "focusSection" | "focusMilestone" | "focusTarget"> {
  if (target.focusSection || target.focusMilestone || target.focusTarget) {
    return {
      focusSection: target.focusSection,
      focusMilestone: target.focusMilestone,
      focusTarget: target.focusTarget,
    };
  }
  const normalized = normalizeMilestoneName(name);
  if (normalized === "scrutiny" || normalized === "controlling") {
    return { focusSection: "Scrutiny and control" };
  }
  if (
    normalized === "highvalue" ||
    normalized === "pretcec" ||
    normalized === "ad" ||
    normalized === "rqa" ||
    normalized === "ifa" ||
    normalized === "cfa" ||
    normalized === "nontcectechnicalevaluation" ||
    normalized === "posttcec" ||
    normalized === "cnc"
  ) {
    return { focusSection: normalized.includes("tcec") ? "TCEC block" : "Approval block" };
  }
  if (normalized === "bidding") return { focusSection: "Bidding details" };
  return { focusSection: "Supply order and payment" };
}

type AnomalyWorkflowTab =
  | "current"
  | "sent"
  | "fileAccepted"
  | "universalAccepted"
  | "rejected"
  | "revoked";

function formatAnomalyStatus(status: string) {
  return status
    .split("_")
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function formatAnomalyScope(scope: string | undefined) {
  return scope === "universal" ? "Universal" : "File";
}

function groupSuspectedAnomalyRows(rows: SuspectedAnomalyRow[]) {
  const groups = new Map<string, SuspectedAnomalyRow[]>();
  rows.forEach((row) => {
    const key = row.rule || row.ruleKey || "Suspected anomaly";
    groups.set(key, [...(groups.get(key) ?? []), row]);
  });
  return Array.from(groups.entries()).map(([title, items]) => ({ title, items }));
}

function groupAnomalyAcceptances(rows: AnomalyAcceptanceRow[]) {
  const groups = new Map<string, AnomalyAcceptanceRow[]>();
  rows.forEach((row) => {
    const key = row.ruleLabel || humanizeCompactAnomalyLabel(row.ruleKey) || "Anomaly exception";
    groups.set(key, [...(groups.get(key) ?? []), row]);
  });
  return Array.from(groups.entries()).map(([title, items]) => ({ title, items }));
}

function humanizeCompactAnomalyLabel(value?: string) {
  if (!value) return "";
  if (value === "fileclosedbutbgreturnpendingexists") {
    return "File is closed but BG return is still pending";
  }
  if (
    value ===
    "stagedeliveryperiodsoverlapacceptableifstagesruninparallelacceptthisanomalyforthisfileifintentional"
  ) {
    return "Stage delivery periods overlap";
  }
  return value
    .replace(/fileclosed/g, "File closed ")
    .replace(/bgreturn/g, " BG return ")
    .replace(/pending/g, " pending ")
    .replace(/exists/g, " exists ")
    .replace(/jobcompletion/g, " Job Completion ")
    .replace(/financialsanction/g, " Financial Sanction ")
    .replace(/supplyorder/g, " Supply Order ")
    .replace(/should/g, " should ")
    .replace(/not/g, " not ")
    .replace(/before/g, " before ")
    .replace(/after/g, " after ")
    .replace(/date/g, " date ")
    .replace(/\s+/g, " ")
    .trim();
}

const anomalyWorkflowTabHelp: Record<AnomalyWorkflowTab, string> = {
  current:
    "Current suspected anomalies still affecting the selected files, including rejected or revoked items if the data issue still exists.",
  sent: "Requests/messages raised for Admin review and still awaiting decision.",
  fileAccepted: "Admin accepted the exception for that specific file only.",
  universalAccepted: "Admin accepted the exception as a general rule for all matching files.",
  rejected: "Admin did not accept the request and sent it back for correction.",
  revoked: "Earlier accepted exception was withdrawn, so the anomaly can appear again.",
};

function SuspectedAnomalyGroupedView({
  rows,
  acceptances,
  isAdmin,
  onRequest,
  onAdminReview,
  onClearSelected,
  onOpenRow,
}: {
  rows: SuspectedAnomalyRow[];
  acceptances: AnomalyAcceptanceRow[];
  isAdmin: boolean;
  onRequest: (row: Record<string, number | string>) => void;
  onAdminReview: (signature: string, action: string) => void;
  onClearSelected: (signatures: string[]) => void;
  onOpenRow: (row: Record<string, number | string>) => void;
}) {
  const [tab, setTab] = useState<AnomalyWorkflowTab>("current");
  const [freeSearch, setFreeSearch] = useState("");
  const [selectedDecisionSignatures, setSelectedDecisionSignatures] = useState<string[]>([]);
  const searchNeedle = freeSearch.trim().toLowerCase();
  const matchesSearch = (row: object) =>
    !searchNeedle || Object.values(row).join(" ").toLowerCase().includes(searchNeedle);
  const currentRows = rows.filter(
    (row) => row.requestStatus !== "pending" && matchesSearch(row),
  );
  const sentRows = rows.filter((row) => row.requestStatus === "pending" && matchesSearch(row));
  const fileAcceptedRows = acceptances.filter(
    (row) => row.status === "approved_file" && matchesSearch(row),
  );
  const universalAcceptedRows = acceptances.filter(
    (row) => row.status === "approved_universal" && matchesSearch(row),
  );
  const rejectedRows = acceptances.filter((row) => row.status === "rejected" && matchesSearch(row));
  const revokedRows = acceptances.filter((row) => row.status === "revoked" && matchesSearch(row));
  const decisionRows =
    tab === "fileAccepted"
      ? fileAcceptedRows
      : tab === "universalAccepted"
        ? universalAcceptedRows
        : tab === "rejected"
          ? rejectedRows
          : tab === "revoked"
            ? revokedRows
            : [];
  const tabs: Array<{ key: AnomalyWorkflowTab; label: string; count: number }> = [
    { key: "current", label: "Current", count: currentRows.length },
    { key: "sent", label: isAdmin ? "Received request" : "Sent", count: sentRows.length },
    { key: "fileAccepted", label: "File Accepted", count: fileAcceptedRows.length },
    { key: "universalAccepted", label: "Universal Accepted", count: universalAcceptedRows.length },
    { key: "rejected", label: "Rejected", count: rejectedRows.length },
    { key: "revoked", label: "Revoked", count: revokedRows.length },
  ];
  const canClearDecisionRows = tab === "rejected" || tab === "revoked";
  const selectedDecisionSet = new Set(selectedDecisionSignatures);
  const currentGroups = groupSuspectedAnomalyRows(currentRows);
  const sentGroups = groupSuspectedAnomalyRows(sentRows);
  const decisionGroups = groupAnomalyAcceptances(decisionRows);
  const currentRowNumberBySignature = new Map(
    currentGroups.flatMap((group) => group.items).map((row, index) => [row.signature, index + 1]),
  );
  const sentRowNumberBySignature = new Map(
    sentGroups.flatMap((group) => group.items).map((row, index) => [row.signature, index + 1]),
  );
  const decisionRowNumberBySignature = new Map(
    decisionGroups.flatMap((group) => group.items).map((row, index) => [row.signature, index + 1]),
  );
  const toggleDecisionSignature = (signature: string) => {
    setSelectedDecisionSignatures((current) =>
      current.includes(signature)
        ? current.filter((item) => item !== signature)
        : [...current, signature],
    );
  };
  useEffect(() => {
    setSelectedDecisionSignatures([]);
  }, [tab]);
  const decisionSignatureKey = decisionRows.map((row) => row.signature).join("|");
  useEffect(() => {
    setSelectedDecisionSignatures((current) =>
      current.filter((signature) => decisionRows.some((row) => row.signature === signature)),
    );
  }, [decisionSignatureKey]);
  const renderActiveGroups = (activeRows: SuspectedAnomalyRow[]) => {
    if (!activeRows.length) {
      return <div className="text-sm text-muted-foreground">No anomalies in this tab.</div>;
    }
    return (
      <div className="space-y-3">
        {(tab === "sent" ? sentGroups : currentGroups).map((group) => (
          <div key={group.title} className="rounded-md border border-border">
            <div className="flex items-center justify-between gap-3 border-b border-border bg-secondary/40 px-3 py-2">
              <h3 className="min-w-0 text-sm font-semibold">
                <CompactTableText value={group.title} width={52} />
              </h3>
              <span className="text-xs text-muted-foreground">{group.items.length} file(s)</span>
            </div>
            <div className="divide-y divide-border/70">
              {group.items.map((row) => (
                <div
                  key={row.signature}
                  className="grid gap-3 px-3 py-3 text-xs md:grid-cols-[3rem_1.2fr_2fr_1.4fr]"
                >
                  <div className="font-semibold text-muted-foreground">
                    {tab === "sent"
                      ? sentRowNumberBySignature.get(row.signature)
                      : currentRowNumberBySignature.get(row.signature)}
                  </div>
                  <div>
                    <button
                      type="button"
                      onClick={() => onOpenRow(row as unknown as Record<string, number | string>)}
                      className="font-semibold text-primary hover:underline"
                    >
                      {row.fileRef}
                    </button>
                    <div className="mt-1 text-muted-foreground">{row.division || "-"}</div>
                    <div className="text-muted-foreground">{row.block}</div>
                  </div>
                  <div className="space-y-1">
                    <div>
                      {row.previousField ? <span className="font-medium">{row.previousField}: </span> : null}
                      {row.previousDate || "-"}
                    </div>
                    <div>
                      {row.laterField ? <span className="font-medium">{row.laterField}: </span> : null}
                      {row.laterDate || "-"}
                    </div>
                    {row.userExplanation ? (
                      <div className="text-muted-foreground">
                        {isAdmin
                          ? `Message from ${row.requestedByName || "User"}`
                          : "Message to Admin"}
                        : {row.userExplanation}
                      </div>
                    ) : null}
                    {row.adminMessage ? (
                      <div className="font-medium text-destructive">
                        Message to User: {row.adminMessage}
                      </div>
                    ) : null}
                  </div>
                  <div className="flex flex-wrap items-start gap-1">
                    {row.requestStatus ? (
                      <span className="rounded border border-border px-2 py-1 font-medium">
                        {formatAnomalyStatus(row.requestStatus)}
                      </span>
                    ) : null}
                    {isAdmin ? (
                      <>
                        <button
                          type="button"
                          onClick={() => onAdminReview(row.signature, "approve_file")}
                          className="rounded border border-border px-2 py-1 font-semibold hover:bg-accent"
                        >
                          Accept file
                        </button>
                        <button
                          type="button"
                          onClick={() => onAdminReview(row.signature, "approve_universal")}
                          className="rounded border border-border px-2 py-1 font-semibold hover:bg-accent"
                        >
                          Accept universal
                        </button>
                        <button
                          type="button"
                          onClick={() => onAdminReview(row.signature, "reject")}
                          className="rounded border border-border px-2 py-1 font-semibold hover:bg-accent"
                        >
                          Send correction to user
                        </button>
                      </>
                    ) : row.requestStatus === "pending" ? (
                      <span className="text-muted-foreground">Message sent to Admin</span>
                    ) : (
                      <button
                        type="button"
                        onClick={() => onRequest(row as unknown as Record<string, number | string>)}
                        className="rounded border border-border px-2 py-1 font-semibold hover:bg-accent"
                      >
                        Send request/message to Admin
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    );
  };

  const renderDecisionRows = (decisionTabRows: AnomalyAcceptanceRow[]) => {
    if (!decisionTabRows.length) {
      return <div className="text-sm text-muted-foreground">No anomalies in this tab.</div>;
    }
    return (
      <div className="space-y-3">
        {decisionGroups.map((group) => (
          <div key={group.title} className="rounded-md border border-border">
            <div className="flex items-center justify-between gap-3 border-b border-border bg-secondary/40 px-3 py-2">
              <h3 className="min-w-0 text-sm font-semibold">
                <CompactTableText value={group.title} width={52} />
              </h3>
              <span className="text-xs text-muted-foreground">{group.items.length} file(s)</span>
            </div>
            <div className="divide-y divide-border/70">
              {group.items.map((row) => (
                <div
                  key={row.signature}
                  className="grid gap-3 px-3 py-3 text-xs md:grid-cols-[3rem_1.1fr_2fr_1fr]"
                >
                  <div className="font-semibold text-muted-foreground">
                    {decisionRowNumberBySignature.get(row.signature)}
                  </div>
                  <div className="flex items-start gap-2">
                    {canClearDecisionRows ? (
                      <input
                        type="checkbox"
                        checked={selectedDecisionSet.has(row.signature)}
                        onChange={() => toggleDecisionSignature(row.signature)}
                        className="mt-0.5"
                        aria-label={`Select ${row.fileRef || "anomaly"}`}
                      />
                    ) : null}
                    <span className="font-semibold">
                      {row.fileRef || "File reference not available"}
                    </span>
                  </div>
                  <div>
                    <div>
                      {row.previousField ? `${row.previousField}: ` : ""}{row.previousValue || "-"}
                    </div>
                    <div>
                      {row.laterField ? `${row.laterField}: ` : ""}{row.laterValue || "-"}
                    </div>
                    {row.reason ? (
                      <div className="mt-1 text-muted-foreground">
                        {isAdmin
                          ? `Message from ${row.requestedByName || "User"}`
                          : "Message to Admin"}
                        : {row.reason}
                      </div>
                    ) : null}
                    {row.adminMessage ? (
                      <div className="mt-1 font-medium text-destructive">
                        Message to User: {row.adminMessage}
                      </div>
                    ) : null}
                  </div>
	                  <div>
	                    <div className="font-medium">{formatAnomalyStatus(row.status)}</div>
	                    <div className="text-muted-foreground">
	                      {formatAnomalyScope(row.scope)} decision
	                    </div>
	                    <div className="text-muted-foreground">
	                      {row.reviewedByName || row.revokedByName || row.requestedByName || "-"}
	                    </div>
                    <div className="text-muted-foreground">
                      {(row.reviewedAt || row.revokedAt || row.requestedAt || "").slice(0, 10)}
                    </div>
                    {isAdmin &&
                    (row.status === "approved_file" || row.status === "approved_universal") ? (
                      <button
                        type="button"
                        onClick={() => onAdminReview(row.signature, "revoke")}
                        className="mt-2 rounded border border-border px-2 py-1 font-semibold hover:bg-accent"
                      >
                        Revoke
                      </button>
                    ) : null}
                    {canClearDecisionRows ? (
                      <button
                        type="button"
                        onClick={() => onClearSelected([row.signature])}
                        className="mt-2 rounded border border-border px-2 py-1 font-semibold text-destructive hover:bg-destructive/10"
                      >
                        Clear
                      </button>
                    ) : null}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-3">
      <div className="flex max-w-2xl items-center gap-2 rounded-md border border-border bg-background px-3">
        <Search className="size-4 shrink-0 text-muted-foreground" />
        <input
          value={freeSearch}
          onChange={(event) => setFreeSearch(event.target.value)}
          placeholder="Free search files, control numbers, descriptions, or anomaly details"
          aria-label="Search suspected anomalies"
          className="h-10 min-w-0 flex-1 bg-transparent text-sm outline-none"
        />
      </div>
      <div className="flex flex-wrap gap-2">
        <TooltipProvider delayDuration={150}>
          {tabs.map((item) => (
            <div key={item.key} className="inline-flex overflow-hidden rounded-md border border-border">
              <button
                type="button"
                onClick={() => setTab(item.key)}
                className={
                  "px-3 py-1.5 text-xs font-semibold " +
                  (tab === item.key ? "bg-primary text-primary-foreground" : "bg-card hover:bg-accent")
                }
              >
                {item.label} ({item.count})
              </button>
              <Tooltip>
                <TooltipTrigger asChild>
                  <button
                    type="button"
                    aria-label={`${item.label} help`}
                    className={
                      "inline-flex w-7 items-center justify-center border-l border-border text-xs " +
                      (tab === item.key
                        ? "bg-primary text-primary-foreground hover:bg-primary/90"
                        : "bg-card text-muted-foreground hover:bg-accent hover:text-foreground")
                    }
                  >
                    <Info className="size-3.5" />
                  </button>
                </TooltipTrigger>
                <TooltipContent
                  side="top"
                  align="start"
                  className="w-fit max-w-[min(48rem,calc(100vw-2rem))] border border-border bg-background p-2 text-foreground shadow-lg text-xs leading-relaxed"
                >
                  {anomalyWorkflowTabHelp[item.key]}
                </TooltipContent>
              </Tooltip>
            </div>
          ))}
        </TooltipProvider>
        {canClearDecisionRows && selectedDecisionSignatures.length ? (
          <button
            type="button"
            onClick={() => onClearSelected(selectedDecisionSignatures)}
            className="rounded-md border border-border bg-card px-3 py-1.5 text-xs font-semibold text-destructive hover:bg-destructive/10"
          >
            Clear selected ({selectedDecisionSignatures.length})
          </button>
        ) : null}
      </div>
      {tab === "current"
        ? renderActiveGroups(currentRows)
        : tab === "sent"
          ? renderActiveGroups(sentRows)
          : renderDecisionRows(decisionRows)}
    </div>
  );
}

function AnalyticsHorizontalBarChart({
  view,
  title,
  divisionValueSingleDivision = false,
  divisionTotalValuePanel = false,
  selectedDivision = "all",
  divisionValueDisplayMode = "both",
  unit,
  columns,
  rows,
  preferValueRangeLabels = false,
  onPlotChange,
  getSearchTarget,
  onOpenSearchTarget,
}: {
  view: ResultView;
  title: string;
  divisionValueSingleDivision?: boolean;
  divisionTotalValuePanel?: boolean;
  selectedDivision?: string;
  divisionValueDisplayMode?: DivisionValueDisplayMode;
  unit?: string;
  columns: AnalyticsTableColumn[];
  rows: Array<Record<string, number | string>>;
  preferValueRangeLabels?: boolean;
  onPlotChange: (plot?: ExportPlot) => void;
  getSearchTarget?: (
    row: Record<string, number | string>,
    column: AnalyticsTableColumn,
  ) => AnalyticsSearchTarget | undefined;
  onOpenSearchTarget?: (target: AnalyticsSearchTarget) => void;
}) {
  const isValueRankingPanel = divisionValueSingleDivision || divisionTotalValuePanel;
  const [selectedMetricKey, setSelectedMetricKey] = useState("");
  const selectedDivisionRow = divisionValueSingleDivision && selectedDivision !== "all"
    ? rows.find((row) => String(row.name ?? "") === selectedDivision)
    : undefined;
  const metrics = columns.filter(
    (column) =>
      column.key !== "rank" && rows.some((row) => typeof row[column.key] === "number"),
  );
  const metric =
    metrics.find((column) => column.key === selectedMetricKey) ??
    metrics.find((column) => column.key === "value" || column.key === "committedTotal") ??
    metrics[0];
  const exportPlot: ExportPlot | undefined = useMemo(() => {
    if (selectedDivisionRow && (view === "bar" || view === "column")) {
      const measures = ["Allocated", "Intended", "Booked", "Committed"] as const;
      return {
        kind: "bar",
        title: `${title} · ${selectedDivision}`,
        measure: "Value",
        unit: divisionValueDisplayMode === "percent" ? "Percent" : "Lakhs",
        xAxisTitle: "Measure",
        yAxisTitle: divisionValueDisplayMode === "percent" ? "Percent of allocation" : "Value (Lakhs)",
        categories: [...measures],
        series: [
          {
            name: "Capital",
            values: measures.map((measure) => {
              const key = `${measure.toLowerCase()}Capital`;
              const amount = Math.max(0, Number(selectedDivisionRow[key]) || 0);
              return divisionValueDisplayMode === "percent"
                ? Number(getPercent(amount, Number(selectedDivisionRow.allocatedCapital)) ?? 0)
                : amount / 100_000;
            }),
          },
          {
            name: "Revenue",
            values: measures.map((measure) => {
              const key = `${measure.toLowerCase()}Revenue`;
              const amount = Math.max(0, Number(selectedDivisionRow[key]) || 0);
              return divisionValueDisplayMode === "percent"
                ? Number(getPercent(amount, Number(selectedDivisionRow.allocatedRevenue)) ?? 0)
                : amount / 100_000;
            }),
          },
        ],
      };
    }
    if (view === "table" || !metric || !rows.length) return undefined;
    const metricText = `${metric.key} ${metric.label} ${unit ?? ""}`;
    const countMetric = /count|files?|cases?|orders?/i.test(`${metric.key} ${metric.label}`);
    const percentMetric = /percent|percentage|share|ratio/i.test(metricText);
    const lakhScale = !percentMetric && (
      (isValueRankingPanel && divisionValueDisplayMode !== "percent") ||
      (!countMetric && /lakh|inr|rupee|₹|amount|value|capital|revenue|payment|allocation|committed|booked|intended/i.test(metricText))
    ) ? 100_000 : 1;
    const denominatorKey = divisionTotalValuePanel
      ? "allocatedTotal"
      : metric.key.endsWith("Revenue") ? "allocatedRevenue" : "allocatedCapital";
    const xKey = preferValueRangeLabels
      ? "range"
      : rows.some((row) => row.month !== undefined)
        ? "month"
        : rows.some((row) => row.monthKey !== undefined)
          ? "monthKey"
          : rows.some((row) => row.year !== undefined)
            ? "year"
            : "name";
    return {
      kind: view === "line" ? "line" : "bar",
      title: `${title} · ${metric.label}`,
      measure: metric.label,
      unit: isValueRankingPanel && divisionValueDisplayMode === "percent"
        ? "Percent"
        : lakhScale > 1 ? "Lakhs" : (unit ?? metric.label),
      xAxisTitle:
        xKey === "month" || xKey === "monthKey"
          ? "Month"
          : xKey === "year"
            ? "Year"
            : /firm/i.test(title)
              ? "Firm Name"
              : /indentor/i.test(title)
                ? "Indentor"
                : "Category",
      yAxisTitle: isValueRankingPanel && divisionValueDisplayMode === "percent"
        ? "Percent of allocation"
        : lakhScale > 1 ? `${metric.label} (Lakhs)` : unit ?? metric.label,
      compactBars: title === "Milestone clearing analysis",
      categories: rows.map((row, index) =>
        String(row[xKey] ?? row.label ?? row.name ?? `Row ${index + 1}`),
      ),
      series: [
        {
          name: metric.label,
          values: rows.map((row) => {
            const value = Math.max(0, Number(row[metric.key]) || 0);
            return isValueRankingPanel && divisionValueDisplayMode === "percent"
              ? Number(getPercent(value, Number(row[denominatorKey])) ?? 0)
              : value / lakhScale;
          }),
        },
      ],
    };
  }, [divisionTotalValuePanel, divisionValueDisplayMode, divisionValueSingleDivision, metric, preferValueRangeLabels, rows, selectedDivision, selectedDivisionRow, title, unit, view]);
  const lastExportPlotRef = useRef<string | undefined>(undefined);
  useEffect(() => {
    const nextPlotKey = exportPlot ? JSON.stringify(exportPlot) : undefined;
    if (lastExportPlotRef.current === nextPlotKey) return;
    lastExportPlotRef.current = nextPlotKey;
    onPlotChange(exportPlot);
  }, [exportPlot, onPlotChange]);
  if (selectedDivisionRow && (view === "bar" || view === "column")) {
    const measureRows = [
      { label: "Allocated", capital: Number(selectedDivisionRow.allocatedCapital) || 0, revenue: Number(selectedDivisionRow.allocatedRevenue) || 0 },
      { label: "Intended", capital: Number(selectedDivisionRow.intendedCapital) || 0, revenue: Number(selectedDivisionRow.intendedRevenue) || 0 },
      { label: "Booked", capital: Number(selectedDivisionRow.bookedCapital) || 0, revenue: Number(selectedDivisionRow.bookedRevenue) || 0 },
      { label: "Committed", capital: Number(selectedDivisionRow.committedCapital) || 0, revenue: Number(selectedDivisionRow.committedRevenue) || 0 },
    ];
    const chartOrientation = view === "column" ? "vertical" : "horizontal";
    return (
      <div className="grid min-w-0 grid-cols-1 items-start gap-4 xl:grid-cols-2">
        {(["capital", "revenue"] as const).map((kind) => (
          <CategoryBarChart
            key={kind}
            title={`${selectedDivision} · ${kind === "capital" ? "Capital" : "Revenue"}`}
            rows={measureRows.map((row) => {
              const allocated = kind === "capital"
                ? Number(selectedDivisionRow.allocatedCapital) || 0
                : Number(selectedDivisionRow.allocatedRevenue) || 0;
              const amount = row[kind];
              const percent = getPercent(amount, allocated);
              const displayValue = formatDivisionValueDisplay(
                amount,
                allocated,
                divisionValueDisplayMode,
              ).replace("\n", " ");
              return {
                label: row.label,
                value: divisionValueDisplayMode === "percent"
                  ? Number(percent ?? 0)
                  : amount,
                displayValue,
              };
            })}
            orientation={chartOrientation}
            formatValue={divisionValueDisplayMode === "percent"
              ? (value) => `${value.toLocaleString("en-IN", { maximumFractionDigits: 1 })}%`
              : formatLakhsValue}
            valueLabel={divisionValueDisplayMode === "percent"
              ? "Percent of allocation"
              : `${kind === "capital" ? "Capital" : "Revenue"} (Lakhs)`}
            horizontalValueLabel={view === "bar"
              ? divisionValueDisplayMode === "percent"
                ? "Percent of allocation"
                : `${kind === "capital" ? "Capital" : "Revenue"} (Lakhs)`
              : undefined}
            maxWidth={640}
          />
        ))}
      </div>
    );
  }

  if (!rows.length || !metric) {
    return <div className="py-8 text-center text-sm text-muted-foreground">No numeric results to chart.</div>;
  }
  const maxValue = Math.max(0, ...rows.map((row) => Number(row[metric.key]) || 0));
  const formatValue = (row: Record<string, number | string>) => {
    const value = row[metric.key] ?? 0;
    return metric.render?.(value, row) ?? metric.format?.(value, row) ?? String(value);
  };
  const metricDescription = `${metric.key} ${metric.label} ${unit ?? ""}`;
  const isPercentMetric = (divisionValueDisplayMode === "percent" && isValueRankingPanel) || /percent|percentage|share|ratio/i.test(metricDescription);
  const isCountMetric = /count|files?|cases?|orders?/i.test(`${metric.key} ${metric.label}`);
  const lakhScale = !isPercentMetric && (
    (isValueRankingPanel && divisionValueDisplayMode !== "percent") ||
    (!isCountMetric && /lakh|inr|rupee|₹|amount|value|capital|revenue|payment|allocation|committed|booked|intended/i.test(metricDescription))
  );
  const axisTitle = isValueRankingPanel && divisionValueDisplayMode === "percent"
    ? "Percent of allocation"
    : lakhScale ? `${metric.label} (Lakhs)` : unit ?? metric.label;

  if (view === "line") {
    const xKey = preferValueRangeLabels
      ? "range"
      : rows.some((row) => row.month !== undefined)
        ? "month"
        : rows.some((row) => row.monthKey !== undefined)
          ? "monthKey"
          : rows.some((row) => row.year !== undefined)
            ? "year"
            : "name";
    const lineValueScale = lakhScale ? 100_000 : 1;
    const denominatorKey = divisionTotalValuePanel
      ? "allocatedTotal"
      : metric.key.endsWith("Revenue") ? "allocatedRevenue" : "allocatedCapital";
    const lineRows = rows.map((row, index) => ({
      ...row,
      chartLabel: String(row[xKey] ?? row.label ?? row.name ?? row.monthKey ?? row.year ?? `Row ${index + 1}`),
      chartValue: isValueRankingPanel && divisionValueDisplayMode === "percent"
        ? Number(getPercent(Number(row[metric.key]) || 0, Number(row[denominatorKey])) ?? 0)
        : Math.max(0, Number(row[metric.key]) || 0) / lineValueScale,
    }));
    return (
      <section data-chart-copy-area aria-label="Trend chart" className="space-y-3">
        <h3 className="text-lg font-semibold text-foreground">{title} · {metric.label}</h3>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p data-chart-copy-exclude className="text-xs text-muted-foreground">Chronological trend from the same filtered result rows.</p>
          {metrics.length > 1 ? (
            <label data-chart-copy-exclude className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
              Measure
              <select value={metric.key} onChange={(event) => setSelectedMetricKey(event.target.value)}
                className="h-8 min-w-44 rounded-md border border-input bg-background px-2 text-sm text-foreground">
                {metrics.map((column) => <option key={column.key} value={column.key}>{column.label}</option>)}
              </select>
            </label>
          ) : null}
          <ChartCopyButton />
        </div>
        <div className="h-[320px] min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={lineRows} margin={{ top: 12, right: 20, left: 8, bottom: 8 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
              <XAxis dataKey="chartLabel" tick={{ fontSize: 13 }} />
              <YAxis
                allowDecimals={false}
                tick={{ fontSize: 13 }}
                width={72}
                tickFormatter={(value) => Number(value).toLocaleString("en-IN", { maximumFractionDigits: 0 })}
                label={{
                  value: axisTitle,
                  angle: -90,
                  position: "insideLeft",
                }}
              />
              <ChartTooltip formatter={(value) => isValueRankingPanel && divisionValueDisplayMode === "percent"
                ? `${Number(value).toLocaleString("en-IN", { maximumFractionDigits: 1 })}%`
                : lineValueScale > 1
                  ? `${Number(value).toLocaleString("en-IN", { maximumFractionDigits: 2 })} Lakh`
                  : Number(value).toLocaleString()} />
              <Line type="monotone" dataKey="chartValue" name={metric.label} stroke="#0f766e" strokeWidth={2} dot={{ r: 4 }} activeDot={{ r: 6 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </section>
    );
  }

  const denominatorKey = divisionTotalValuePanel
    ? "allocatedTotal"
    : metric.key.endsWith("Revenue") ? "allocatedRevenue" : "allocatedCapital";
  const chartRows = rows.map((row, index) => {
    const label = String(
      (preferValueRangeLabels ? row.range : undefined) ??
        row.name ?? row.division ?? row.label ?? `Result ${index + 1}`,
    );
    const target = getSearchTarget?.(row, metric);
    return {
      label,
      value: isValueRankingPanel && divisionValueDisplayMode === "percent"
        ? Number(getPercent(Number(row[metric.key]) || 0, Number(row[denominatorKey])) ?? 0)
        : Math.max(0, Number(row[metric.key]) || 0),
      displayValue: formatValue(row),
      onClick: target && onOpenSearchTarget ? () => onOpenSearchTarget(target) : undefined,
    };
  });
  return (
    <div className="space-y-2">
      {metrics.length > 1 ? (
        <div className="flex justify-end">
          <label data-chart-copy-exclude className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
            Measure
            <select value={metric.key} onChange={(event) => setSelectedMetricKey(event.target.value)} className="h-8 min-w-32 max-w-56 rounded-md border border-input bg-background px-2 text-sm text-foreground">
              {metrics.map((column) => <option key={column.key} value={column.key}>{column.group ? `${column.group} · ` : ""}{column.label}</option>)}
            </select>
          </label>
        </div>
      ) : null}
      <CategoryBarChart
        title={`${title} · ${metric.label}`}
        rows={chartRows}
        orientation={view === "column" ? "vertical" : "horizontal"}
        formatValue={(value) => value.toLocaleString("en-IN")}
        valueLabel={axisTitle}
        horizontalValueLabel={view === "bar" ? axisTitle : undefined}
        maxWidth={640}
        showHorizontalAxis={view === "bar"}
        showColumnAxis={view === "column"}
      />
    </div>
  );
}

function TcecCommitteeBreakupChart({
  view,
  rows,
}: {
  view: ResultView;
  rows: Array<Record<string, number | string>>;
}) {
  const horizontal = view === "bar";
  const chartHeight = Math.max(300, Math.min(620, rows.length * 44 + 100));
  const series = [
    { key: "reviewed", label: "Files reviewed", color: getChartColorAt(0) },
    { key: "signed", label: "Minutes signed", color: getChartColorAt(1) },
    { key: "pending", label: "Minutes pending", color: getChartColorAt(2) },
  ];

  return (
    <section
      data-chart-copy-area
      aria-label="TCEC committee breakup chart"
      className="space-y-3 rounded-md border border-border bg-background p-3"
    >
      <div className="flex items-center justify-between gap-3">
        <h4 data-chart-copy-title className="text-sm font-semibold">TCEC committee breakup</h4>
        <ChartCopyButton />
      </div>
      <div className="h-px bg-border" />
      <div className="w-full min-w-0 rounded-md border border-border/80 bg-card p-2">
        <ResponsiveContainer width="100%" height={chartHeight}>
          <BarChart
            data={rows}
            layout={horizontal ? "vertical" : "horizontal"}
            margin={{ top: 12, right: 20, bottom: horizontal ? 12 : 82, left: horizontal ? 8 : 8 }}
            barCategoryGap="22%"
          >
            <CartesianGrid stroke="var(--border)" strokeDasharray="3 3" />
            {horizontal ? (
              <>
                <XAxis
                  type="number"
                  allowDecimals={false}
                  tick={{ fontSize: 12 }}
                  tickFormatter={(value) => Number(value).toLocaleString("en-IN")}
                />
                <YAxis
                  type="category"
                  dataKey="name"
                  width={160}
                  tick={{ fontSize: 12 }}
                  interval={0}
                />
              </>
            ) : (
              <>
                <XAxis
                  dataKey="name"
                  interval={0}
                  height={88}
                  angle={-42}
                  textAnchor="end"
                  tickMargin={8}
                  tick={{ fontSize: 11 }}
                />
                <YAxis
                  allowDecimals={false}
                  width={52}
                  tick={{ fontSize: 12 }}
                  tickFormatter={(value) => Number(value).toLocaleString("en-IN")}
                />
              </>
            )}
            <ChartTooltip
              formatter={(value, name) => [Number(value ?? 0).toLocaleString("en-IN"), name]}
              labelFormatter={(label) => String(label)}
            />
            <Legend wrapperStyle={{ fontSize: 12 }} />
            {series.map((item) => (
              <Bar
                key={item.key}
                dataKey={item.key}
                name={item.label}
                fill={item.color}
                maxBarSize={22}
                radius={0}
              />
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
}

function TcecStatusStackedBarChart({
  view,
  title,
  stage,
  rows,
  onPlotChange,
  getSearchTarget,
  onOpenSearchTarget,
}: {
  view: ResultView;
  title: string;
  stage: TcecStatusStage;
  rows: Array<Record<string, number | string>>;
  onPlotChange: (plot?: ExportPlot) => void;
  getSearchTarget?: (
    row: Record<string, number | string>,
    column: AnalyticsTableColumn,
  ) => AnalyticsSearchTarget | undefined;
  onOpenSearchTarget?: (target: AnalyticsSearchTarget) => void;
}) {
  const signedColor = getChartColorAt(0);
  const pendingColor = getChartColorAt(1);
  const totalColor = getChartColorAt(2);
  const exportPlot: ExportPlot | undefined = useMemo(() => {
    if (!rows.length) return undefined;
    const xKey = rows.some((row) => row.meetingDate !== undefined) ? "meetingDate" : "name";
    return {
      kind: "bar",
      title: `${title} · ${stage === "pre" ? "Pre-TCEC" : "Post-TCEC"}`,
      measure: "Files reviewed",
      unit: "Files",
      xAxisTitle: xKey === "meetingDate" ? "Meeting date" : "Committee / FY",
      yAxisTitle: "Files",
      stackedBars: true,
      categories: rows.map((row, index) =>
        String(row[xKey] ?? row.name ?? `Row ${index + 1}`),
      ),
      series: [
        { name: "Minutes signed", values: rows.map((row) => Number(row.signed) || 0), color: signedColor },
        { name: "Minutes pending", values: rows.map((row) => Number(row.pending) || 0), color: pendingColor },
      ],
    };
  }, [rows, stage, title]);
  const lastExportPlotRef = useRef<string | undefined>(undefined);
  useEffect(() => {
    const nextPlotKey = exportPlot ? JSON.stringify(exportPlot) : undefined;
    if (lastExportPlotRef.current === nextPlotKey) return;
    lastExportPlotRef.current = nextPlotKey;
    onPlotChange(exportPlot);
  }, [exportPlot, onPlotChange]);

  if (!rows.length) {
    return <div className="py-8 text-center text-sm text-muted-foreground">No TCEC results to chart.</div>;
  }
  const maximum = Math.max(1, ...rows.map((row) => Number(row.reviewed) || 0));
  const segments = [
    { key: "signed", label: "Minutes signed", color: signedColor },
    { key: "pending", label: "Minutes pending", color: pendingColor },
  ] as const;

  if (view === "column") {
    const plotHeight = 250;
    const chartTicks = Array.from({ length: 5 }, (_, index) => Math.round(maximum * (4 - index) / 4));
    return (
      <section data-chart-copy-area aria-label="TCEC status column chart" className="mx-auto w-full min-w-0 space-y-3 rounded-md border border-border bg-background p-4">
        <div className="grid min-w-0 grid-cols-[1fr_auto_1fr] items-center gap-2">
          <span aria-hidden="true" />
          <h3 data-chart-copy-title className="min-w-0 truncate text-center text-xl font-semibold text-foreground">{`${title} · ${stage === "pre" ? "Pre-TCEC" : "Post-TCEC"}`}</h3>
          <div className="flex items-center justify-self-end gap-3 text-sm text-muted-foreground">
            <span>Files</span><ChartCopyButton />
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-4 border-b border-border pb-2 text-sm text-muted-foreground">
          {segments.map((segment) => <span key={segment.key} className="inline-flex items-center gap-1.5"><span className="size-3 rounded-sm" style={{ backgroundColor: segment.color }} />{segment.label}</span>)}
        </div>
        <div className="w-full min-w-0 overflow-hidden rounded-md border border-border/80 bg-card p-2 sm:p-3">
        <div className="flex min-w-0 gap-2 sm:gap-3" style={{ height: 432 }}>
          <div className="relative w-[100px] shrink-0 sm:w-[108px]" aria-hidden="true">
            <span className="absolute left-0 top-[22px] flex items-center justify-center text-sm font-medium text-muted-foreground [writing-mode:vertical-rl] rotate-180" style={{ height: plotHeight }}>Files</span>
            {chartTicks.map((value, index) => <span key={`${value}-${index}`} className="absolute right-0 w-[58px] -translate-y-1/2 text-right text-sm tabular-nums text-muted-foreground" style={{ top: 26 + (index / 4) * plotHeight }}>{value}</span>)}
          </div>
          <div role="group" aria-label={`${title} stacked column chart`} className="relative grid min-w-0 flex-1 grid-rows-[26px_250px_156px] gap-0 border border-border/80 bg-background" style={{ gridTemplateColumns: `repeat(${rows.length}, minmax(0, 1fr))` }}>
          <div className="pointer-events-none absolute inset-x-0 top-[26px] h-[250px]" aria-hidden="true">
            {chartTicks.map((value, index) => <div key={index} className={`absolute inset-x-0 ${index === 4 ? "border-t-2 border-border" : "border-t border-border/60"}`} style={{ top: index * 62.5 }} />)}
          </div>
          {rows.map((row, index) => {
            const label = String(row.name ?? `Result ${index + 1}`);
            const reviewed = Math.max(0, Number(row.reviewed) || 0);
            const signed = Math.max(0, Number(row.signed) || 0);
            const pending = Math.max(0, Number(row.pending) || 0);
            const target = getSearchTarget?.(row, { key: "reviewed", label: "Files reviewed" });
            const contents = <><span className="truncate text-sm font-semibold tabular-nums">{reviewed}</span><span className="relative z-[1] flex h-[250px] items-end justify-center px-0.5"><span className="flex w-5 max-w-5 flex-col justify-end overflow-hidden border-2 bg-background" style={{ height: `${reviewed ? Math.max(0, reviewed / maximum * 100) : 0}%`, borderColor: totalColor }}><span style={{ height: `${reviewed ? pending / reviewed * 100 : 0}%`, backgroundColor: pendingColor }} /><span className="block" style={{ height: `${reviewed ? signed / reviewed * 100 : 0}%`, backgroundColor: signedColor }} /></span></span><span className="relative block h-[156px] overflow-visible text-sm text-muted-foreground"><span className="absolute left-1/2 top-2 w-32 origin-top-left rotate-[58deg] text-left" title={label}>{label}</span></span></>;
            return target && onOpenSearchTarget ? <button key={`${label}-${index}`} type="button" onClick={() => onOpenSearchTarget(target)} title={`Open ${label} results in Search Files`} className="grid min-w-0 grid-rows-[26px_250px_156px] text-center hover:bg-accent/30">{contents}</button> : <div key={`${label}-${index}`} className="grid min-w-0 grid-rows-[26px_250px_156px] text-center">{contents}</div>;
              })}
          </div>
        </div>
        </div>
      </section>
    );
  }

  return (
    <section data-chart-copy-area aria-label="TCEC status chart" className="space-y-3 rounded-md border border-border bg-background p-4">
      <div className="flex min-w-0 items-center justify-between gap-3">
        <h3 className="min-w-0 truncate text-xl font-semibold text-foreground">{title} · {stage === "pre" ? "Pre-TCEC" : "Post-TCEC"}</h3>
        <ChartCopyButton />
      </div>
      <div className="flex flex-wrap items-center gap-4 border-b border-border pb-2 text-sm text-muted-foreground">
        <span className="inline-flex items-center gap-1.5">
          <span className="size-3 rounded-sm border-2" style={{ borderColor: totalColor }} />
          Files reviewed (total)
        </span>
        {segments.map((segment) => (
          <span key={segment.key} className="inline-flex items-center gap-1.5">
            <span className="size-3 rounded-sm" style={{ backgroundColor: segment.color }} />
            {segment.label}
          </span>
        ))}
        <span className="ml-auto">Files</span>
      </div>
      <div role="group" aria-label={`${title} stacked bar chart`} className="space-y-2 rounded-md border border-border/80 bg-card p-3">
        {rows.map((row, index) => {
          const label = String(row.name ?? `Result ${index + 1}`);
          const reviewed = Math.max(0, Number(row.reviewed) || 0);
          const signed = Math.max(0, Number(row.signed) || 0);
          const pending = Math.max(0, Number(row.pending) || 0);
          const target = getSearchTarget?.(row, { key: "reviewed", label: "Files reviewed" });
          const chart = (
            <>
              <span className="w-40 shrink-0 truncate text-left text-sm font-medium" title={label}>{label}</span>
              <span className="min-w-0 flex-1 pt-5">
                <span className="relative block h-6 overflow-visible bg-secondary/70">
                  <span
                  className="flex h-full overflow-hidden border-2 bg-background"
                  style={{ width: `${(reviewed / maximum) * 100}%`, borderColor: totalColor }}
                  role="img"
                  aria-label={`${label}: ${reviewed} files reviewed; ${signed} minutes signed; ${pending} minutes pending`}
                >
                  {segments.map((segment) => {
                    const value = segment.key === "signed" ? signed : pending;
                    const width = reviewed > 0 ? (value / reviewed) * 100 : 0;
                    return (
                      <span
                        key={segment.key}
                        className="block h-full shrink-0"
                        style={{ width: `${width}%`, backgroundColor: segment.color }}
                        title={`${segment.label}: ${value}`}
                      />
                    );
                  })}
                  </span>
                  <span className="absolute -top-5 -translate-x-full whitespace-nowrap text-sm font-medium tabular-nums text-foreground" style={{ left: `${(reviewed / maximum) * 100}%` }}>Reviewed: {reviewed}</span>
                </span>
              </span>
            </>
          );
          return target && onOpenSearchTarget ? (
            <button
              key={`${label}-${index}`}
              type="button"
              onClick={() => onOpenSearchTarget(target)}
              className="flex w-full items-center gap-3 rounded-sm py-1 hover:bg-accent/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              title={`Open ${label} results in Search Files`}
            >
              {chart}
            </button>
          ) : (
            <div key={`${label}-${index}`} className="flex items-center gap-3 py-1">{chart}</div>
          );
        })}
      </div>
    </section>
  );
}

function AnalyticsRankingTable({
  columns,
  rows,
  getRowNameHelpText,
  compactRankColumn = false,
  wideNameColumn = false,
  getCellSearchTarget,
  getColumnTotalSearchTarget,
  onOpenSearchTarget,
}: {
  columns: AnalyticsTableColumn[];
  rows: Array<Record<string, number | string>>;
  getRowNameHelpText?: (row: Record<string, number | string>) => string[] | undefined;
  compactRankColumn?: boolean;
  wideNameColumn?: boolean;
  getCellSearchTarget?: (
    row: Record<string, number | string>,
    column: AnalyticsTableColumn,
  ) => AnalyticsSearchTarget | undefined;
  getColumnTotalSearchTarget?: (column: AnalyticsTableColumn) => AnalyticsSearchTarget | undefined;
  onOpenSearchTarget?: (target: AnalyticsSearchTarget) => void;
}) {
  if (!rows.length) {
    return <div className="text-sm text-muted-foreground">No data available.</div>;
  }
  const groupedHeaders = getAnalyticsGroupedHeaders(columns);
  const hasGroupedHeaders = groupedHeaders.some((header) => header.group);
  const totalCells = getAnalyticsTotalCells(columns, rows, getColumnTotalSearchTarget);
  const showTotalFooter =
    Boolean(onOpenSearchTarget) &&
    totalCells.some((cell, index) => index > 0 && cell.searchTarget && cell.value !== "0");

  return (
    <div className="overflow-x-auto">
      <table
        className={`w-full ${wideNameColumn ? "min-w-[820px]" : compactRankColumn ? "min-w-[720px]" : "min-w-[980px]"} table-fixed border-collapse text-sm`}
      >
        <colgroup>
          {columns.map((column, index) => (
            <col
              key={column.key}
              style={column.width ? { width: column.width } : undefined}
              className={
                index === 0 && compactRankColumn
                  ? "w-12"
                  : index === 1 && wideNameColumn
                    ? "w-64"
                    : wideNameColumn && column.key === "supplyOrderCount"
                      ? "w-20"
                      : wideNameColumn && column.key === "city"
                        ? "w-36"
                    : index === 0
                      ? "w-40"
                      : "w-32"
              }
            />
          ))}
        </colgroup>
        <thead>
          {hasGroupedHeaders ? (
            <>
              <tr className="border-b border-border text-xs uppercase text-muted-foreground">
                {groupedHeaders.map((header, index) => (
                  <th
                    key={header.key}
                    colSpan={header.colSpan}
                    rowSpan={header.group ? 1 : 2}
                    className={
                      "px-3 py-2 font-medium " +
                      getAnalyticsHeaderSectionClass(
                        header.group,
                        groupedHeaders[index - 1]?.group,
                      ) +
                      (header.align === "left" ? "text-left" : "text-center")
                    }
                  >
                    {header.label}
                  </th>
                ))}
              </tr>
              <tr className="border-b border-border text-xs uppercase text-muted-foreground">
                {columns
                  .map((column, index) => ({ column, index }))
                  .filter(({ column }) => column.group)
                  .map(({ column, index }) => (
                    <th
                      key={column.key}
                      className={
                        "px-3 py-2 text-center font-medium " +
                        getAnalyticsColumnSectionClass(column, columns[index - 1])
                      }
                    >
                      {column.label}
                    </th>
                  ))}
              </tr>
            </>
          ) : (
            <tr className="border-b border-border text-xs uppercase text-muted-foreground">
              {columns.map((column) => (
                <th
                  key={column.key}
                  className={
                    "px-3 py-2 font-medium " +
                    (column.align === "left" ? "text-left" : "text-center")
                  }
                >
                  {column.label}
                </th>
              ))}
            </tr>
          )}
        </thead>
        <tbody>
          {rows.map((row, rowIndex) => (
            <tr
              key={String(
                row.relationshipKey ?? row.signature ?? row.uniqueNumber ?? row.name ?? row.fileRef ?? rowIndex,
              )}
              className="border-b border-border/60 last:border-0"
            >
              {columns.map((column, columnIndex) => {
                const value = row[column.key] ?? "";
                const renderedValue = column.render
                  ? column.render(value, row)
                  : column.format
                    ? column.format(value, row)
                    : String(value);
                const textWidth =
                  typeof renderedValue === "string"
                    ? getCompactTableTextWidth(column.key, column.label)
                    : undefined;
                const compactValue = textWidth ? (
                  <CompactTableText value={String(renderedValue)} width={textWidth} />
                ) : (
                  renderedValue
                );
                const searchTarget = getCellSearchTarget?.(row, column);
                const content =
                  searchTarget && onOpenSearchTarget ? (
                    <button
                      type="button"
                      onClick={() => onOpenSearchTarget(searchTarget)}
                      className="rounded-md px-2 py-1 font-semibold text-primary hover:bg-primary/10"
                    >
                      {compactValue}
                    </button>
                  ) : (
                    compactValue
                  );
                const rowNameHelpText =
                  column.key === "name" ? getRowNameHelpText?.(row) : undefined;
                return (
                  <td
                    key={column.key}
                    className={
                      "whitespace-pre-line px-3 py-2 tabular-nums " +
                      getAnalyticsColumnSectionClass(column, columns[columnIndex - 1]) +
                      (column.align === "left" ? "text-left font-medium" : "text-center")
                    }
                  >
                    {rowNameHelpText ? (
                      <span className="inline-flex items-center gap-1.5">
                        {content}
                        <TooltipProvider delayDuration={150}>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <button
                                type="button"
                                tabIndex={-1}
                                aria-label={`About ${String(row.name ?? "milestone")}`}
                                className="inline-flex size-5 shrink-0 items-center justify-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
                              >
                                <Info className="size-3.5" />
                              </button>
                            </TooltipTrigger>
                            <TooltipContent side="right" className="max-w-72 leading-relaxed">
                              <ul className="list-disc space-y-1 pl-4">
                                {rowNameHelpText.map((item) => (
                                  <li key={item}>{item}</li>
                                ))}
                              </ul>
                            </TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                      </span>
                    ) : (
                      content
                    )}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
        {showTotalFooter ? (
          <tfoot>
            <tr className="border-t border-border bg-muted/40 font-semibold">
              {totalCells.map((cell, index) => (
                <td
                  key={columns[index]?.key ?? index}
                  className={
                    "whitespace-pre-line px-3 py-2 tabular-nums " +
                    getAnalyticsColumnSectionClass(columns[index], columns[index - 1]) +
                    ((columns[index]?.align ?? "right") === "left"
                      ? "text-left font-medium"
                      : "text-center")
                  }
                >
                  {cell.searchTarget &&
                  onOpenSearchTarget &&
                  (index === 0 || cell.value !== "0") ? (
                    <button
                      type="button"
                      onClick={() => onOpenSearchTarget(cell.searchTarget!)}
                      className="rounded-md px-2 py-1 font-semibold text-primary hover:bg-primary/10"
                    >
                      {cell.value}
                    </button>
                  ) : (
                    cell.value
                  )}
                </td>
              ))}
            </tr>
          </tfoot>
        ) : null}
      </table>
    </div>
  );
}

function getAnalyticsHeaderSectionClass(
  group: string | undefined,
  previousGroup: string | undefined,
) {
  if (!group) return "";
  const tint = getAnalyticsSectionTintClass(group);
  const divider = previousGroup !== group ? "border-l border-border " : "";
  return `${divider}${tint}`;
}

function getAnalyticsColumnSectionClass(
  column: AnalyticsTableColumn | undefined,
  previousColumn: AnalyticsTableColumn | undefined,
) {
  const group = column?.group;
  if (!group) return "";
  const tint = getAnalyticsSectionTintClass(group);
  const divider = previousColumn?.group !== group ? "border-l border-border " : "";
  return `${divider}${tint}`;
}

function getAnalyticsSectionTintClass(group: string) {
  const normalizedGroup = group.toLowerCase();
  if (normalizedGroup.includes("value")) return "bg-muted/30 ";
  return "bg-muted/10 ";
}

function getAnalyticsTotalCells(
  columns: AnalyticsTableColumn[],
  rows: Array<Record<string, number | string>>,
  getColumnTotalSearchTarget?: (column: AnalyticsTableColumn) => AnalyticsSearchTarget | undefined,
) {
  const numericCells = columns.slice(1).map((column) => {
    const total = rows.reduce((sum, row) => {
      const value = Number(row[column.key] ?? 0);
      return Number.isFinite(value) ? sum + value : sum;
    }, 0);
    const formattedValue = column.format ? column.format(total, {}) : String(total);
    return {
      value: formattedValue,
      searchTarget: getColumnTotalSearchTarget?.(column),
    };
  });
  const primaryTotalTarget = numericCells.find(
    (cell) => cell.searchTarget && cell.value !== "0",
  )?.searchTarget;
  return [{ value: "Total", searchTarget: primaryTotalTarget }, ...numericCells];
}

