  onBgToBeReturnedClick,
  onBgReturnedClick,
  onAdvancePaidClick,
  onAdvancePendingClick,
  onAllPaymentPendingClick,
  onPaymentDueClick,
  onPaymentInProcessClick,
  onPaymentSubmittedClick,
